insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t01_v4', 'tpl_t01', 4, '[{"id":"candidate_name","section":{"en":"Candidate","fr":"Candidat"},"label":{"en":"Candidate full name","fr":"Nom complet du candidat"},"type":"text","required":true,"placeholder":{"en":"e.g. Gabriel Dubois","fr":"p. ex. Gabriel Dubois"}},{"id":"position_title","section":{"en":"Role","fr":"Poste"},"label":{"en":"Position title","fr":"Titre du poste"},"type":"text","required":true,"placeholder":{"en":"e.g. Field technician","fr":"p. ex. technicien de terrain"}},{"id":"manager_name","section":{"en":"Role","fr":"Poste"},"label":{"en":"Reports to","fr":"Relève de"},"type":"text","required":true,"placeholder":{"en":"e.g. Operations Manager","fr":"p. ex. directeur des opérations"}},{"id":"employment_type","section":{"en":"Role","fr":"Poste"},"label":{"en":"Employment type","fr":"Type d’emploi"},"type":"radio","required":true,"options":[{"value":"full-time","label":{"en":"Full-time","fr":"Temps plein"}},{"value":"part-time","label":{"en":"Part-time","fr":"Temps partiel"}}]},{"id":"start_date","section":{"en":"Timing","fr":"Échéancier"},"label":{"en":"Start date","fr":"Date d’entrée en fonction"},"type":"date","required":true},{"id":"work_location","section":{"en":"Timing","fr":"Échéancier"},"label":{"en":"Primary work location","fr":"Lieu de travail principal"},"type":"text","required":true,"placeholder":{"en":"e.g. Ottawa, ON (hybrid)","fr":"p. ex. Ottawa (ON), hybride"}},{"id":"annual_salary","section":{"en":"Compensation","fr":"Rémunération"},"label":{"en":"Annual salary (CAD)","fr":"Salaire annuel (CAD)"},"type":"text","required":true,"placeholder":{"en":"e.g. 68,000","fr":"p. ex. 68 000"}},{"id":"vacation_weeks","section":{"en":"Compensation","fr":"Rémunération"},"label":{"en":"Vacation","fr":"Vacances"},"type":"select","required":true,"options":[{"value":"2 weeks","label":{"en":"2 weeks (statutory minimum)","fr":"2 semaines (minimum légal)"}},{"value":"3 weeks","label":{"en":"3 weeks","fr":"3 semaines"}},{"value":"4 weeks","label":{"en":"4 weeks","fr":"4 semaines"}}]},{"id":"probation","section":{"en":"Terms","fr":"Conditions"},"label":{"en":"Probationary period","fr":"Période de probation"},"type":"select","required":true,"options":[{"value":"no","label":{"en":"None","fr":"Aucune"}},{"value":"3-month","label":{"en":"3 months","fr":"3 mois"}},{"value":"6-month","label":{"en":"6 months","fr":"6 mois"}}]}]'::jsonb, '[{"type":"title","text":{"en":"Offer of Employment","fr":"Offre d’emploi"}},{"type":"meta","text":{"en":"{{org}} · {{today}} · {{jurisdiction}}","fr":"{{org}} · {{today}} · {{jurisdiction}}"}},{"type":"para","text":{"en":"Dear {{candidate_name}}, we are pleased to offer you the position of {{position_title}}, reporting to {{manager_name}}, on a {{employment_type}} basis.","fr":"Cher/Chère {{candidate_name}}, nous avons le plaisir de vous offrir le poste de {{position_title}}, relevant de {{manager_name}}, à titre {{employment_type}}."}},{"type":"clause","text":{"en":"Your employment begins on {{start_date}}. Your primary work location is {{work_location}}.","fr":"Votre emploi débute le {{start_date}}. Votre lieu de travail principal est {{work_location}}."},"n":1,"heading":{"en":"Start date & location","fr":"Date et lieu"}},{"type":"clause","text":{"en":"You will earn an annual salary of ${{annual_salary}} CAD, less statutory deductions, with {{vacation_weeks}} of paid vacation at or above the minimum for {{jurisdiction}}.","fr":"Vous gagnerez un salaire annuel de {{annual_salary}} $ CAD, moins les retenues légales, avec {{vacation_weeks}} de vacances payées, au moins égales au minimum pour {{jurisdiction}}."},"n":2,"heading":{"en":"Compensation","fr":"Rémunération"}},{"type":"clause","text":{"en":"A {{probation}} probationary period applies. Either party may end this employment per the applicable standards for {{jurisdiction}}, including any required notice or pay in lieu.","fr":"Une période de probation de {{probation}} s’applique. Chaque partie peut mettre fin à l’emploi selon les normes applicables pour {{jurisdiction}}, y compris tout avis ou indemnité en tenant lieu."},"n":3,"heading":{"en":"Probation & termination","fr":"Probation et cessation"}},{"type":"para","text":{"en":"This offer is conditional on satisfactory reference and eligibility-to-work checks. To accept, sign and return by the date discussed.","fr":"Cette offre est conditionnelle à des vérifications de références et d’admissibilité satisfaisantes. Pour l’accepter, signez et retournez avant la date convenue."}},{"type":"clause","text":{"en":"Because {{org}} employs 25 or more employees in Ontario, you will receive a copy of the written policy on disconnecting from work required by the Employment Standards Act, 2000.","fr":"Comme {{org}} emploie 25 salariés ou plus en Ontario, vous recevrez une copie de la politique écrite sur la déconnexion exigée par la Loi de 2000 sur les normes d’emploi."},"heading":{"en":"Disconnecting from work","fr":"Droit à la déconnexion"},"when":{"juris":"ON","min_headcount":25}},{"type":"sig","roles":[{"en":"Employer representative","fr":"Représentant de l’employeur"},{"en":"Employee","fr":"Employé(e)"}]},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"Employment Standards Act, 2000 — minimum standards","fr":"Loi de 2000 sur les normes d’emploi — normes minimales"},{"en":"Human Rights Code — non-discrimination in hiring","fr":"Code des droits de la personne — non-discrimination à l’embauche"}]'::jsonb, '{"ON":{"en":"Terms may not fall below ESA, 2000 minimums; a non-compliant termination clause can void the clause entirely.","fr":"Les conditions ne peuvent être sous les minimums de la LNE; une clause de cessation non conforme peut être invalidée."},"QC":{"en":"Reflect the Act respecting labour standards; probation does not remove Civil Code notice obligations.","fr":"Refléter la Loi sur les normes du travail; la probation ne supprime pas les obligations d’avis du Code civil."},"FED":{"en":"Federally regulated employers follow the Canada Labour Code, Part III for notice, hours, and vacation.","fr":"Les employeurs fédéraux suivent le Code canadien du travail, Partie III."}}'::jsonb, '[{"en":"Position & reporting","fr":"Poste et lien hiérarchique"},{"en":"Start date & location","fr":"Date et lieu"},{"en":"Compensation","fr":"Rémunération"},{"en":"Hours of work","fr":"Heures de travail"},{"en":"Vacation & benefits","fr":"Vacances et avantages"},{"en":"Probation","fr":"Probation"},{"en":"Termination","fr":"Cessation"},{"en":"Conditional offer & acceptance","fr":"Offre conditionnelle et acceptation"}]'::jsonb, '<h1 class="center">Offer of Employment</h1>
<p class="date"><span class="mf">{{document_date}}</span></p>
<address><span class="mf">{{candidate_name}}</span><br><span class="mf">{{candidate_address_line_1}}</span><br><span class="mf">{{candidate_address_line_2}}</span></address>
<p class="re"><strong>Re:</strong> Offer of employment — <span class="mf">{{position_title}}</span></p>
<p>Dear <span class="mf">{{candidate_first_name}}</span>,</p>
<p>We are pleased to offer you the position of <strong><span class="mf">{{position_title}}</span></strong> at <strong><span class="mf">{{employer_legal_name}}</span></strong> (the <strong>Company</strong>), reporting to <strong><span class="mf">{{manager_name}}</span></strong>. This letter sets out the principal terms of your employment. Please review it carefully and, if everything looks right, sign and return a copy by <span class="mf">{{offer_expiry_date}}</span>.</p>
<h2>1. Start date and location</h2>
<p>Your first day will be <span class="mf">{{start_date}}</span>, and you will be based at <span class="mf">{{work_location}}</span>. Your employment is <span class="mf">{{employment_type}}</span>.</p>
<h2>2. Compensation</h2>
<p>You will earn an annual base salary of <span class="mf">{{annual_base_salary}}</span> CAD, paid <span class="mf">{{pay_frequency}}</span> by direct deposit, less statutory deductions.</p>
<h2>3. Hours of work and overtime</h2>
<p>Your regular hours will be <span class="mf">{{scheduled_hours_per_week}}</span> hours per week. Overtime is paid in accordance with the Employment Standards Act, 2000, s. 22, at 1.5× your regular rate for hours worked beyond the statutory threshold, unless your role is exempt as a manager or supervisor under O. Reg. 285/01.</p>
<h2>4. Vacation and statutory holidays</h2>
<p>You will receive <span class="mf">{{vacation_weeks}}</span> weeks of paid vacation per year, meeting or exceeding the minimum required by ESA ss. 33–34. You will also be paid for all statutory public holidays recognized in your jurisdiction.</p>
<h2>5. Benefits</h2>
<p>You will be eligible for the Company''s <span class="mf">{{benefits_plan_name}}</span> group benefits plan starting <span class="mf">{{benefits_start_date}}</span>, in accordance with the plan''s terms.</p>
<h2>6. Probationary period</h2>
<p>The first <span class="mf">{{probation_length}}</span> of your employment is a probationary period during which your fit for the role will be assessed. Statutory notice obligations continue to apply throughout.</p>
<h2>7. Termination</h2>
<p>Either party may end this employment in accordance with the Employment Standards Act, 2000. On a without-cause termination, you will receive at least the notice (or pay in lieu) and severance, if applicable, required by ESA ss. 54–65. If any part of this offer would provide less than the statutory minimum, that part is void and the statutory minimum applies instead, consistent with <em>Waksdale v. Swegon</em>, 2020 ONCA 391.</p>
<h2>8. Confidentiality and intellectual property</h2>
<p>As a condition of employment, you agree to keep the Company''s confidential information confidential during and after your employment, and that any work product created in the course of your role belongs to the Company. Full terms are set out in your Employment Agreement and Confidentiality Agreement, provided alongside this offer.</p>
<h2>9. Conditions of this offer</h2>
<p>This offer is conditional on: (a) your ability to legally work in Canada; (b) satisfactory completion of the background and reference checks we have described to you; and (c) your signature of the Employment Agreement and related policies by <span class="mf">{{start_date}}</span>.</p>
<p>If you have any questions, please reach out — we are happy to walk through anything with you.</p>
<p class="signoff-closing">Welcome to the team,</p>
<p class="signoff-name"><span class="mf">{{employer_signer_name}}</span></p>
<p class="signoff-line"><span class="mf">{{employer_signer_title}}</span></p>
<p class="signoff-line"><span class="mf">{{employer_legal_name}}</span></p>', '2026-05-01', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t02', 'hiring', 'employment_agreement', 'T02', 'agreement', true, 'employee', 'Employment agreement (indefinite term)', 'Contrat de travail (durée indéterminée)', 'A full indefinite-term contract. The termination clause is the highest-exposure section — drafted with Waksdale in mind.', 'Un contrat complet à durée indéterminée. La clause de cessation est la section la plus exposée — rédigée en tenant compte de l’arrêt Waksdale.', array['ON','QC','FED']::text[], 'medium', 'hr_review_required', false, 12, 74, '2026-04-10', '2026-06-18');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t02_v3', 'tpl_t02', 3, '[{"id":"employee_name","section":{"en":"Parties","fr":"Parties"},"label":{"en":"Employee full name","fr":"Nom complet de l’employé(e)"},"type":"text","required":true,"placeholder":{"en":"Full legal name","fr":"Nom légal complet"}},{"id":"position_title","section":{"en":"Role","fr":"Poste"},"label":{"en":"Position title","fr":"Titre du poste"},"type":"text","required":true,"placeholder":{"en":"e.g. Account manager","fr":"p. ex. gestionnaire de comptes"}},{"id":"start_date","section":{"en":"Term","fr":"Durée"},"label":{"en":"Start date","fr":"Date de début"},"type":"date","required":true},{"id":"scheduled_hours_per_week","section":{"en":"Hours","fr":"Heures"},"label":{"en":"Scheduled hours per week","fr":"Heures prévues par semaine"},"type":"number","required":true,"placeholder":{"en":"40","fr":"40"}},{"id":"annual_base_salary","section":{"en":"Compensation","fr":"Rémunération"},"label":{"en":"Annual base salary (CAD)","fr":"Salaire de base annuel (CAD)"},"type":"text","required":true,"placeholder":{"en":"e.g. 82,000","fr":"p. ex. 82 000"}},{"id":"vacation_weeks","section":{"en":"Compensation","fr":"Rémunération"},"label":{"en":"Vacation (weeks)","fr":"Vacances (semaines)"},"type":"number","required":true,"placeholder":{"en":"3","fr":"3"}},{"id":"termination_basis","section":{"en":"Termination","fr":"Cessation"},"label":{"en":"Termination clause basis","fr":"Base de la clause de cessation"},"type":"radio","required":true,"hint":{"en":"Statutory-only limits exposure but must be drafted precisely.","fr":"Le minimum légal limite l’exposition mais doit être rédigé précisément."},"options":[{"value":"statutory minimum","label":{"en":"Statutory minimum only","fr":"Minimum légal seulement"}},{"value":"enhanced","label":{"en":"Enhanced (above minimum)","fr":"Bonifié (au-dessus du minimum)"}}]}]'::jsonb, '[{"type":"title","text":{"en":"Employment Agreement","fr":"Contrat de travail"}},{"type":"para","text":{"en":"This Employment Agreement is entered into on {{today}} between {{org}} (the Employer) and {{employee_name}} (the Employee).","fr":"Le présent contrat de travail est conclu le {{today}} entre {{org}} (l’Employeur) et {{employee_name}} (l’Employé(e))."}},{"type":"clause","text":{"en":"The Employee is engaged as {{position_title}}, effective {{start_date}}, on an indefinite-term basis, working {{scheduled_hours_per_week}} hours per week.","fr":"L’employé(e) est engagé(e) à titre de {{position_title}}, à compter du {{start_date}}, pour une durée indéterminée, à raison de {{scheduled_hours_per_week}} heures par semaine."},"n":1,"heading":{"en":"Position & start","fr":"Poste et début"}},{"type":"clause","text":{"en":"Base salary is ${{annual_base_salary}} CAD per year, less statutory deductions, with {{vacation_weeks}} weeks of paid vacation — never below the minimum for {{jurisdiction}}.","fr":"Le salaire de base est de {{annual_base_salary}} $ CAD par année, moins les retenues légales, avec {{vacation_weeks}} semaines de vacances payées — jamais sous le minimum pour {{jurisdiction}}."},"n":2,"heading":{"en":"Compensation & vacation","fr":"Rémunération et vacances"}},{"type":"clause","text":{"en":"On a without-cause termination, the Employee receives entitlements on the {{termination_basis}} basis, never less than the minimums required for {{jurisdiction}}. If any part would provide less, that part is void and the statutory minimum applies.","fr":"En cas de cessation sans motif, l’employé(e) reçoit ses droits sur la base {{termination_basis}}, jamais inférieurs aux minimums pour {{jurisdiction}}. Toute clause offrant moins est nulle et le minimum légal s’applique."},"n":3,"heading":{"en":"Ending the employment","fr":"Fin de l’emploi"}},{"type":"clause","text":{"en":"Confidential information and work product created in the role belong to {{org}}.","fr":"Les renseignements confidentiels et les livrables créés dans le cadre du poste appartiennent à {{org}}."},"n":4,"heading":{"en":"Confidentiality & IP","fr":"Confidentialité et PI"}},{"type":"clause","text":{"en":"Because {{org}} employs 25 or more employees in Ontario, you will receive a copy of the written policy on disconnecting from work required by the Employment Standards Act, 2000.","fr":"Comme {{org}} emploie 25 salariés ou plus en Ontario, vous recevrez une copie de la politique écrite sur la déconnexion exigée par la Loi de 2000 sur les normes d’emploi."},"heading":{"en":"Disconnecting from work","fr":"Droit à la déconnexion"},"when":{"juris":"ON","min_headcount":25}},{"type":"sig","roles":[{"en":"Employer representative","fr":"Représentant de l’employeur"},{"en":"Employee","fr":"Employé(e)"}]},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"Employment Standards Act, 2000 / Canada Labour Code","fr":"Loi de 2000 sur les normes d’emploi / Code canadien du travail"},{"en":"Waksdale v. Swegon, 2020 ONCA 391","fr":"Waksdale c. Swegon, 2020 ONCA 391"},{"en":"McKinley v. BC Tel, 2001 SCC 38","fr":"McKinley c. BC Tel, 2001 CSC 38"},{"en":"Meiorin — BC v. BCGSEU, 1999","fr":"Meiorin — C.-B. c. BCGSEU, 1999"}]'::jsonb, '{"ON":{"en":"A termination clause must clearly meet or exceed ESA minimums, or a court may award common-law notice instead (Waksdale).","fr":"La clause de cessation doit atteindre ou dépasser les minimums de la LNE, sinon le préavis de common law s’applique (Waksdale)."},"QC":{"en":"Québec is civil law; the Civil Code governs notice and good faith. Restrictive covenants are read narrowly.","fr":"Le Québec est de droit civil; le Code civil régit l’avis et la bonne foi. Les clauses restrictives sont interprétées restrictivement."},"FED":{"en":"Unjust-dismissal protection under CLC s. 240 may apply after 12 months of continuous service.","fr":"La protection contre le congédiement injuste (CCT art. 240) peut s’appliquer après 12 mois de service continu."}}'::jsonb, '[{"en":"Parties & role","fr":"Parties et poste"},{"en":"Start date & type","fr":"Date et type"},{"en":"Place of work & hours","fr":"Lieu et heures"},{"en":"Compensation","fr":"Rémunération"},{"en":"Vacation & benefits","fr":"Vacances et avantages"},{"en":"Confidentiality & IP","fr":"Confidentialité et PI"},{"en":"Termination","fr":"Cessation"},{"en":"Restrictive covenants","fr":"Clauses restrictives"},{"en":"Governing law","fr":"Loi applicable"}]'::jsonb, '<h1 class="center">Employment Agreement</h1>
<p>This Employment Agreement (the <strong>Agreement</strong>) is made on <span class="mf">{{agreement_date}}</span>.</p>
<h2>Between</h2>
<p><strong><span class="mf">{{employer_legal_name}}</span></strong>, with its principal office at <span class="mf">{{employer_address}}</span> (the <strong>Company</strong>),</p>
<p>— and —</p>
<p><strong><span class="mf">{{employee_name}}</span></strong>, of <span class="mf">{{employee_address}}</span> (the <strong>Employee</strong>).</p>
<h2>1. Position and reporting</h2>
<p>The Employee is engaged as <span class="mf">{{position_title}}</span>, effective <span class="mf">{{start_date}}</span>, on an indefinite-term basis, reporting to <span class="mf">{{manager_name}}</span>. The Employee will perform the duties normally associated with the role and any other reasonable duties assigned by the Company.</p>
<h2>2. Compensation</h2>
<p>Base salary is <span class="mf">{{annual_base_salary}}</span> CAD per year, paid <span class="mf">{{pay_frequency}}</span>, less statutory deductions, reviewed at the Company''s discretion.</p>
<h2>3. Hours of work and overtime</h2>
<p>Scheduled hours are <span class="mf">{{scheduled_hours_per_week}}</span> per week. Overtime, where applicable, is paid in accordance with the Employment Standards Act, 2000, s. 22.</p>
<h2>4. Vacation and statutory holidays</h2>
<p>The Employee is entitled to <span class="mf">{{vacation_weeks}}</span> weeks of paid vacation per year, never below the minimum required by ESA ss. 33–35.2, plus all statutory public holidays.</p>
<h2>5. Benefits and expenses</h2>
<p>The Employee is eligible for the Company''s group benefits plan on the terms set out in the plan documents, and will be reimbursed for reasonable, pre-approved business expenses incurred in the performance of their duties.</p>
<h2>6. Confidentiality and intellectual property</h2>
<p>The Employee will keep the Company''s confidential information confidential during and after employment. All work product created in the course of the role belongs to the Company, including copyright and other intellectual property rights, to the fullest extent permitted by law.</p>
<h2>7. Termination</h2>
<p>On a without-cause termination, the Employee will receive the greater of the notice (or pay in lieu) and severance, if applicable, required by the Employment Standards Act, 2000, ss. 54–65, or <span class="mf">{{enhanced_notice_description}}</span>. If any part of this clause would provide less than the statutory minimum in the circumstances at the time notice is given, that part is void and the statutory minimum governs instead, consistent with <em>Waksdale v. Swegon</em>, 2020 ONCA 391. The Company may terminate the Employee''s employment for just cause without notice or pay in lieu, assessed contextually in accordance with <em>McKinley v. BC Tel</em>, 2001 SCC 38.</p>
<h2>8. Return of property</h2>
<p>On the end of employment for any reason, the Employee will promptly return all Company property, including devices, access cards, keys, and any physical or electronic materials containing Company information.</p>
<h2>9. Restrictive covenants</h2>
<p>The Employee''s non-solicitation and (where lawful) non-competition obligations are set out in the Company''s standard Restrictive Covenants Agreement, incorporated by reference. Non-competition applies only where permitted under ESA s. 67.2 (executive or sale-of-business exceptions); for all other employees in Ontario, no non-compete applies.</p>
<h2>10. General</h2>
<p>This Agreement is governed by the laws of the Province of <span class="mf">{{governing_province}}</span>. It is the entire agreement between the parties concerning its subject matter and may only be amended in writing signed by both parties. The Employee confirms having had the opportunity to obtain independent legal advice before signing.</p>
<p>By signing below, the parties confirm they have read and accept the terms of this Agreement.</p>
<div class="spacer">&nbsp;</div>
<table class="sig"><tr>
<td><div class="sig-line">_______________________________</div><div class="sig-under">Signature — <span class="mf">{{employer_signer_name}}</span></div><div class="sig-under"><span class="mf">{{employer_signer_title}}</span></div><div class="sig-under">Date: <span class="mf">{{employer_signature_date}}</span></div><div class="sig-label">COMPANY</div></td>
<td><div class="sig-line">_______________________________</div><div class="sig-under">Signature — <span class="mf">{{employee_name}}</span></div><div class="sig-under"><span class="mf">{{employee_position}}</span></div><div class="sig-under">Date: <span class="mf">{{employee_signature_date}}</span></div><div class="sig-label">EMPLOYEE</div></td>
</tr></table>', '2026-04-10', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t03', 'termination', 'termination_letter', 'T03', 'letter', true, 'employee', 'Termination letter (without cause)', 'Lettre de cessation d’emploi (sans motif)', 'Ends employment without cause. High exposure — confirm notice, severance, and benefit continuation before sending.', 'Met fin à l’emploi sans motif. Exposition élevée — confirmez l’avis, l’indemnité et le maintien des avantages avant l’envoi.', array['ON','QC','FED']::text[], 'high', 'lawyer_review_recommended', true, 10, 41, '2026-03-12', '2026-06-16');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t03_v3', 'tpl_t03', 3, '[{"id":"employee_name","section":{"en":"Employee","fr":"Employé"},"label":{"en":"Employee full name","fr":"Nom complet de l’employé(e)"},"type":"text","required":true,"placeholder":{"en":"Full legal name","fr":"Nom légal complet"}},{"id":"tenure_years","section":{"en":"Service","fr":"Service"},"label":{"en":"Years of continuous service","fr":"Années de service continu"},"type":"number","required":true,"placeholder":{"en":"e.g. 6","fr":"p. ex. 6"}},{"id":"effective_date","section":{"en":"Timing","fr":"Échéancier"},"label":{"en":"Termination effective date","fr":"Date d’effet de la cessation"},"type":"date","required":true},{"id":"notice_weeks","section":{"en":"Entitlements","fr":"Droits"},"label":{"en":"Notice / pay in lieu (weeks)","fr":"Avis / indemnité (semaines)"},"type":"number","required":true,"hint":{"en":"Must meet or exceed the statutory minimum for the jurisdiction.","fr":"Doit atteindre ou dépasser le minimum légal de la juridiction."}},{"id":"severance_weeks","section":{"en":"Entitlements","fr":"Droits"},"label":{"en":"Severance (weeks, if applicable)","fr":"Indemnité de départ (semaines, si applicable)"},"type":"number","required":false},{"id":"benefits_end","section":{"en":"Entitlements","fr":"Droits"},"label":{"en":"Benefits continue until","fr":"Avantages maintenus jusqu’au"},"type":"date","required":true}]'::jsonb, '[{"type":"title","text":{"en":"Termination of Employment","fr":"Cessation d’emploi"}},{"type":"meta","text":{"en":"{{org}} · {{today}} · {{jurisdiction}}","fr":"{{org}} · {{today}} · {{jurisdiction}}"}},{"type":"para","text":{"en":"Dear {{employee_name}}, this letter confirms that your employment with {{org}} will end, without cause, effective {{effective_date}} after {{tenure_years}} years of service.","fr":"Cher/Chère {{employee_name}}, la présente confirme que votre emploi chez {{org}} prendra fin, sans motif, le {{effective_date}}, après {{tenure_years}} ans de service."}},{"type":"clause","text":{"en":"You will receive {{notice_weeks}} weeks of notice (or pay in lieu) plus {{severance_weeks}} weeks of severance where applicable — meeting or exceeding the minimums for {{jurisdiction}}.","fr":"Vous recevrez {{notice_weeks}} semaines d’avis (ou indemnité) plus {{severance_weeks}} semaines d’indemnité de départ le cas échéant — au moins égales aux minimums pour {{jurisdiction}}."},"n":1,"heading":{"en":"Notice & severance","fr":"Avis et indemnité"}},{"type":"clause","text":{"en":"Group benefits continue until {{benefits_end}}. Your final pay includes all earned wages and accrued vacation.","fr":"Les avantages collectifs sont maintenus jusqu’au {{benefits_end}}. Votre paie finale comprend tous les salaires gagnés et les vacances accumulées."},"n":2,"heading":{"en":"Benefits & final pay","fr":"Avantages et paie finale"}},{"type":"clause","text":{"en":"We can provide a reference and outplacement support. Please return company property by your last day.","fr":"Nous pouvons fournir une référence et un soutien au reclassement. Veuillez retourner les biens de l’entreprise au dernier jour."},"n":3,"heading":{"en":"Support","fr":"Soutien"}},{"type":"clause","text":{"en":"This workplace is unionized: the collective agreement and its grievance procedure govern this process, and this document must follow the negotiated steps and timelines.","fr":"Ce milieu de travail est syndiqué : la convention collective et sa procédure de grief régissent ce processus, et le présent document doit suivre les étapes et les délais négociés."},"heading":{"en":"Collective agreement","fr":"Convention collective"},"when":{"union":true}},{"type":"sig","roles":[{"en":"Employer representative","fr":"Représentant de l’employeur"},{"en":"Employee","fr":"Employé(e)"}]},{"type":"note","text":{"en":"Higher-risk document. Lawyer review is recommended before this is sent or signed. Dutiva does not provide legal advice.","fr":"Document à risque élevé. Une révision juridique est recommandée avant l’envoi ou la signature. Dutiva ne fournit pas de conseils juridiques."},"tone":"risk"}]'::jsonb, '[{"en":"ESA, 2000 ss. 54–65 — notice & severance","fr":"LNE, 2000 art. 54–65 — avis et indemnité"},{"en":"Canada Labour Code ss. 230, 235","fr":"Code canadien du travail art. 230, 235"},{"en":"Common-law reasonable notice (outside QC)","fr":"Préavis raisonnable de common law (hors QC)"}]'::jsonb, '{"ON":{"en":"Provide the greater of ESA notice/severance or common-law notice; continue benefits through the statutory notice period.","fr":"Offrir le plus élevé de l’avis/indemnité LNE ou du préavis de common law; maintenir les avantages durant l’avis légal."},"QC":{"en":"The Civil Code requires reasonable notice; LSA sets minimums and prohibits dismissal without good and sufficient cause after 2 years.","fr":"Le Code civil exige un avis raisonnable; la LNT fixe des minimums et interdit le congédiement sans cause juste et suffisante après 2 ans."},"FED":{"en":"CLC notice (s. 230) and severance (s. 235) apply; unjust-dismissal recourse (s. 240) may apply after 12 months.","fr":"L’avis (art. 230) et l’indemnité (art. 235) du CCT s’appliquent; le recours pour congédiement injuste (art. 240) après 12 mois."}}'::jsonb, '[{"en":"Effective date","fr":"Date d’effet"},{"en":"Reason (without cause)","fr":"Motif (sans motif)"},{"en":"Notice / pay in lieu","fr":"Avis / indemnité"},{"en":"Severance","fr":"Indemnité de départ"},{"en":"Benefit continuation","fr":"Maintien des avantages"},{"en":"Final pay & vacation","fr":"Paie finale et vacances"},{"en":"Return of property","fr":"Retour des biens"},{"en":"Support resources","fr":"Ressources de soutien"}]'::jsonb, '<p class="date"><span class="mf">{{document_date}}</span></p>
<address><span class="mf">{{employee_name}}</span><br><span class="mf">{{employee_address_line_1}}</span><br><span class="mf">{{employee_address_line_2}}</span></address>
<p class="re"><strong>Re:</strong> End of your employment with <span class="mf">{{employer_legal_name}}</span></p>
<p>Dear <span class="mf">{{employee_first_name}}</span>,</p>
<p>This letter confirms our conversation today. We have decided to end your employment with <strong><span class="mf">{{employer_legal_name}}</span></strong> (the <strong>Company</strong>) on a without-cause basis, effective <strong><span class="mf">{{termination_effective_date}}</span></strong>. We know this is difficult news. We want to make the transition as respectful, clear and practical as we can — and this letter sets out what you can expect from us.</p>
<h2>1. Why we''re making this decision</h2>
<p>The reason for ending your employment is <strong><span class="mf">{{termination_reason}}</span></strong>. This is not a decision about your character or your effort. Where appropriate, we will provide a neutral employment reference to prospective employers; please direct reference requests to <strong><span class="mf">{{reference_contact_name}}</span></strong> at <strong><span class="mf">{{reference_contact_email}}</span></strong>.</p>
<h2>2. Your final day</h2>
<p>Your last working day is <strong><span class="mf">{{last_working_day}}</span></strong>. After that date, you will be on a paid notice period through <strong><span class="mf">{{notice_period_end_date}}</span></strong>, during which you are not required to perform any duties unless we agree otherwise. Your employment formally ends on <strong><span class="mf">{{termination_effective_date}}</span></strong>.</p>
<h2>3. Your separation package</h2>
<p>In recognition of your service and in full satisfaction of the Company''s obligations to you under your employment agreement and applicable employment standards legislation, the Company will provide the following:</p>
<ul><li><strong>Notice of termination (or pay in lieu):</strong> <strong><span class="mf">{{notice_weeks}}</span></strong> weeks, paid at your regular base salary, less statutory deductions. This meets or exceeds the minimum notice required by ESA ss. 54–57 (the Employment Standards Act, 2000 governs your employment).</li><li><strong>Statutory severance pay:</strong> <strong><span class="mf">{{severance_weeks}}</span></strong> weeks, paid at your regular base salary, less statutory deductions, as required by ESA s. 64. 1 week per completed year of service (max 26 weeks), where employer payroll ≥ $2.5M and employee has 5+ years.</li><li><strong>Vacation pay:</strong> All accrued and unused vacation up to <strong><span class="mf">{{termination_effective_date}}</span></strong>, less statutory deductions.</li><li><strong>Benefits continuation:</strong> Your group benefits (health, dental, life and disability) will continue until <strong><span class="mf">{{benefits_end_date}}</span></strong>, which covers at least the statutory notice period. We will send you information about continuation or conversion options before that date.</li><li><strong>Outstanding business expenses:</strong> Any approved expenses you submit by <strong><span class="mf">{{expense_deadline}}</span></strong> will be reimbursed in the normal way.</li></ul>
<p>The Company will pay your final wages, vacation pay and notice of termination no later than the employee''s next regular pay date or earlier if required by applicable law. Your Record of Employment will be issued within the timelines required by the Employment Insurance Regulations.</p>
<h2>4. Enhanced offer — conditional on a release</h2>
<p>In addition to what the Company is required to provide, and to support you while you look for your next role, the Company is offering you an enhanced severance package of <strong><span class="mf">{{enhanced_severance_amount}}</span></strong>, conditional on you signing the Full and Final Release attached to this letter. You are not required to accept this enhanced package — you will still receive everything in section 3 regardless. We encourage you to obtain independent legal advice before deciding.</p>
<p>If you wish to accept, please sign and return the Release by <strong><span class="mf">{{release_deadline}}</span></strong>. We are genuinely happy to extend that deadline if you need more time — just ask <strong><span class="mf">{{hr_contact_name}}</span></strong>.</p>
<h2>5. Things to return</h2>
<p>By <strong><span class="mf">{{return_property_date}}</span></strong>, please return all Company property in your possession, including laptops, phones, access cards, keys, credit cards, and any physical or electronic documents containing Company information. We will make this easy — <strong><span class="mf">{{hr_contact_name}}</span></strong> will coordinate pickup or shipping with you.</p>
<h2>6. Ongoing obligations</h2>
<p>Your confidentiality and intellectual property obligations under your employment agreement continue after your last day and are not affected by this letter. These obligations do not limit your right to make a protected disclosure to a regulator, to participate in a human-rights or whistleblower complaint, or to discuss your wages and working conditions with others as permitted by law.</p>
<h2>7. Support through the transition</h2>
<p>We know this moment is hard and we want to help. The following supports are available to you at no cost:</p>
<ul><li><strong>Career transition support</strong> through <strong><span class="mf">{{career_transition_provider}}</span></strong>, for up to <strong><span class="mf">{{career_transition_duration}}</span></strong>.</li><li><strong>Employee and Family Assistance Program</strong> — confidential counselling for you and your family, available for <strong><span class="mf">{{eap_continuation_period}}</span></strong> after your last day.</li><li>A conversation with <strong><span class="mf">{{hr_contact_name}}</span></strong> at <strong><span class="mf">{{hr_contact_email}}</span></strong> any time you have questions about this letter, the process, or anything else.</li></ul>
<h2>8. Your rights</h2>
<p>This letter is provided in good faith and is intended to comply with — and in several respects exceed — the minimum requirements of the employment standards legislation that applies to your province, human rights legislation, and any other applicable law. If you believe any part of this letter is inconsistent with those minimums, please let us know and we will correct it. Nothing in this letter, including the Release, waives any right that cannot be waived under applicable law.</p>
<h2>9. Closing</h2>
<p>Thank you for everything you have contributed during your time with the Company. We wish you the very best in what comes next.</p>
<p>If anything in this letter is unclear, please reach out — we are here to talk it through.</p>
<p class="signoff-closing">With respect and our best wishes,</p><p class="signoff-name"><span class="mf">{{employer_signer_name}}</span></p><p class="signoff-line"><span class="mf">{{employer_signer_title}}</span></p><p class="signoff-line"><span class="mf">{{employer_legal_name}}</span></p>', '2026-03-12', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t04', 'policies', 'employee_handbook', 'T04', 'handbook', true, 'org', 'Employee handbook', 'Manuel de l’employé', 'The consolidated guide to how the workplace runs — conduct, hours, leave, and where to get help.', 'Le guide regroupé du fonctionnement du milieu — conduite, heures, congés et ressources.', array['ON','QC','FED']::text[], 'low', 'hr_review_required', false, 14, 63, '2026-01-10', '2026-06-18');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t04_v5', 'tpl_t04', 5, '[{"id":"effective_date","section":{"en":"Basics","fr":"Bases"},"label":{"en":"Effective date","fr":"Date d’entrée en vigueur"},"type":"date","required":true},{"id":"hr_contact","section":{"en":"Support","fr":"Soutien"},"label":{"en":"HR / people contact","fr":"Contact RH / personnes"},"type":"text","required":true,"placeholder":{"en":"e.g. people@northgate.ca","fr":"p. ex. personnes@northgate.ca"}}]'::jsonb, '[{"type":"title","text":{"en":"Employee Handbook","fr":"Manuel de l’employé"}},{"type":"meta","text":{"en":"{{org}} · Effective {{effective_date}} · {{jurisdiction}}","fr":"{{org}} · En vigueur le {{effective_date}} · {{jurisdiction}}"}},{"type":"clause","text":{"en":"This handbook explains how {{org}} works and what we expect of each other. It sits alongside — and never below — the minimum standards for {{jurisdiction}}.","fr":"Ce manuel explique le fonctionnement de {{org}} et nos attentes mutuelles. Il complète — sans jamais réduire — les normes minimales pour {{jurisdiction}}."},"n":1,"heading":{"en":"Welcome","fr":"Bienvenue"}},{"type":"clause","text":{"en":"Questions and concerns can be raised with {{hr_contact}} at any time, without fear of reprisal.","fr":"Les questions et préoccupations peuvent être adressées à {{hr_contact}} en tout temps, sans crainte de représailles."},"n":2,"heading":{"en":"Getting help","fr":"Obtenir de l’aide"}},{"type":"ack","text":{"en":"I acknowledge I have read and understood this document.","fr":"Je reconnais avoir lu et compris le présent document."}},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"Employment Standards Act, 2000","fr":"Loi de 2000 sur les normes d’emploi"},{"en":"Occupational Health and Safety Act","fr":"Loi sur la santé et la sécurité au travail"},{"en":"Human Rights Code","fr":"Code des droits de la personne"}]'::jsonb, '{"ON":{"en":"Include the written policy on disconnecting from work (ESA) if you have 25+ employees.","fr":"Inclure la politique écrite sur la déconnexion (LNE) si vous comptez 25 employés et plus."},"QC":{"en":"Reference the LSA and psychological-harassment obligations; provide in French.","fr":"Référer à la LNT et aux obligations sur le harcèlement psychologique; fournir en français."},"FED":{"en":"Reflect Canada Labour Code standards and the harassment-and-violence regulations.","fr":"Refléter les normes du Code canadien du travail et le règlement sur le harcèlement et la violence."}}'::jsonb, '[{"en":"Welcome & values","fr":"Bienvenue et valeurs"},{"en":"Hours & pay","fr":"Heures et paie"},{"en":"Time off & leave","fr":"Congés"},{"en":"Conduct & respect","fr":"Conduite et respect"},{"en":"Health & safety","fr":"Santé-sécurité"},{"en":"Where to get help","fr":"Où obtenir de l’aide"}]'::jsonb, '<h1 class="center">Employee Handbook</h1>
<p class="center"><strong>Effective:</strong> <span class="mf">{{handbook_effective_date}}</span></p>
<h2>Welcome</h2>
<p>This handbook explains how <span class="mf">{{employer_legal_name}}</span> works and what we expect of each other. It sits alongside — and never below — the minimum standards set by the employment standards legislation that applies to your province. Where a specific policy (Code of Conduct, Harassment Prevention, Vacation & Leave, Remote Work) covers a topic in more detail, that policy governs the specifics; this handbook is the map.</p>
<h2>1. Employment basics</h2>
<p>Employees are classified as full-time, part-time, or fixed-term, as set out in their offer letter and employment agreement. Your classification determines eligibility for certain benefits and leaves.</p>
<h2>2. Hours of work and attendance</h2>
<p>Standard hours and overtime eligibility are set out in your employment agreement, consistent with the Employment Standards Act, 2000, ss. 17–22. Please notify your manager as early as possible if you cannot attend as scheduled.</p>
<h2>3. Compensation and pay</h2>
<p>Pay dates, deductions, and how to raise a pay question are posted at <span class="mf">{{payroll_info_url}}</span>. Wage statements are provided each pay period as required by ESA s. 12.</p>
<h2>4. Vacation and leaves</h2>
<p>Vacation, sick leave, and statutory job-protected leaves are governed by our Vacation & Leave Policy, which meets or exceeds ESA ss. 33–50.1. See <span class="mf">{{policy_hub_url}}</span> for the current version.</p>
<h2>5. Workplace conduct</h2>
<p>Our Code of Conduct sets the standard for honesty, respect, conflicts of interest, and use of company property. Everyone — employees, contractors, and leaders alike — is expected to know and follow it.</p>
<h2>6. Health and safety</h2>
<p>We are committed to a safe workplace under the Occupational Health and Safety Act, R.S.O. 1990, c. O.1. You have the right to know about workplace hazards, to participate in health and safety activities, and to refuse unsafe work. Report hazards or incidents to <span class="mf">{{hs_contact_name}}</span> immediately.</p>
<h2>7. Harassment, discrimination and violence prevention</h2>
<p>Our Workplace Harassment, Discrimination and Violence Prevention Policy sets out prohibited conduct, how to report a concern, and how we investigate, consistent with OHSA ss. 32.0.1–32.0.8 and the Human Rights Code, R.S.O. 1990, c. H.19.</p>
<h2>8. Privacy and confidentiality</h2>
<p>We collect and use personal information only for legitimate business purposes, consistent with PIPEDA (federal baseline) and, in Québec, Law 25. Confidential business information must be protected during and after your employment.</p>
<h2>9. Technology and electronic monitoring</h2>
<p>Company systems are provided for business use. Where required by ESA s. 41.1.1 (employers with 25+ employees), our Electronic Monitoring Policy describes what is monitored and why; ask <span class="mf">{{it_contact_name}}</span> for details.</p>
<h2>10. Progressive discipline</h2>
<p>Where performance or conduct concerns arise, we generally follow a progressive approach — informal conversation, written warning, and, where necessary, further action up to termination — assessed contextually in accordance with <em>McKinley v. BC Tel</em>, 2001 SCC 38.</p>
<h2>11. Termination and resignation</h2>
<p>Termination entitlements follow the Employment Standards Act, 2000 and your employment agreement. If you resign, please provide notice consistent with your role and let <span class="mf">{{hr_contact_name}}</span> know as soon as possible so we can plan a smooth handover.</p>
<h2>12. Changes to this handbook</h2>
<p>This handbook is reviewed at least annually and may be updated to reflect changes in the law or our practices. Where a legislated minimum changes, the statutory minimum applies automatically even before a formal update. The current version is always available at <span class="mf">{{policy_hub_url}}</span>.</p>
<h2>13. Acknowledgement</h2>
<p><strong>Acknowledgement of receipt.</strong> My signature below confirms that I have received, read, and understand this handbook, and that I know where to go with questions.</p>
<div class="spacer">&nbsp;</div>
<table class="sig"><tr>
<td><div class="sig-line">_______________________________</div><div class="sig-under">Signature — <span class="mf">{{employee_name}}</span></div><div class="sig-under"><span class="mf">{{employee_position}}</span></div><div class="sig-under">Date: <span class="mf">{{employee_signature_date}}</span></div><div class="sig-label">EMPLOYEE — ACKNOWLEDGED</div></td>
</tr></table>', '2026-01-10', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t05', 'agreements', 'confidentiality_agreement', 'T05', 'agreement', true, 'employee', 'Confidentiality agreement', 'Entente de confidentialité', 'Protects confidential business, client, and personal information handled during employment.', 'Protège les renseignements confidentiels d’affaires, clients et personnels traités durant l’emploi.', array['ON','QC','FED']::text[], 'medium', 'hr_review_required', false, 7, 38, '2026-02-15', '2026-05-14');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t05_v2', 'tpl_t05', 2, '[{"id":"employee_name","section":{"en":"Party","fr":"Partie"},"label":{"en":"Employee full name","fr":"Nom complet de l’employé(e)"},"type":"text","required":true,"placeholder":{"en":"Full legal name","fr":"Nom légal complet"}},{"id":"effective_date","section":{"en":"Basics","fr":"Bases"},"label":{"en":"Effective date","fr":"Date d’entrée en vigueur"},"type":"date","required":true}]'::jsonb, '[{"type":"title","text":{"en":"Confidentiality Agreement","fr":"Entente de confidentialité"}},{"type":"para","text":{"en":"Between {{org}} and {{employee_name}}, effective {{effective_date}}.","fr":"Entre {{org}} et {{employee_name}}, en vigueur le {{effective_date}}."}},{"type":"clause","text":{"en":"The Employee will keep confidential all non-public information about {{org}}, its clients, personnel, finances, and technology, and use it only to perform the role.","fr":"L’employé(e) gardera confidentiels tous les renseignements non publics sur {{org}}, ses clients, son personnel, ses finances et sa technologie, et les utilisera uniquement pour ses fonctions."},"n":1,"heading":{"en":"Confidential information","fr":"Renseignements confidentiels"}},{"type":"clause","text":{"en":"This does not limit protected disclosures to a regulator, whistleblower or human-rights complaints, or discussing wages and working conditions as permitted by law.","fr":"Ceci ne limite pas les divulgations protégées à un organisme, les plaintes de dénonciation ou de droits de la personne, ni la discussion des salaires et conditions permise par la loi."},"n":2,"heading":{"en":"Protected disclosures","fr":"Divulgations protégées"}},{"type":"sig","roles":[{"en":"Employer representative","fr":"Représentant de l’employeur"},{"en":"Employee","fr":"Employé(e)"}]},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"Common-law duty of confidence","fr":"Obligation de confidentialité de common law"},{"en":"PIPEDA / Law 25 for personal information","fr":"LPRPDE / Loi 25 pour les renseignements personnels"}]'::jsonb, '{"ON":{"en":"Protected disclosures to a regulator and discussion of wages remain permitted.","fr":"Les divulgations protégées à un organisme et les discussions salariales demeurent permises."},"QC":{"en":"Personal information is also governed by Law 25 obligations.","fr":"Les renseignements personnels sont aussi régis par les obligations de la Loi 25."},"FED":{"en":"Whistleblower protections under federal law are preserved.","fr":"Les protections des dénonciateurs de la loi fédérale sont préservées."}}'::jsonb, '[{"en":"Definition of confidential information","fr":"Définition des renseignements confidentiels"},{"en":"Permitted use","fr":"Usage permis"},{"en":"Return of materials","fr":"Retour des documents"},{"en":"Protected disclosures","fr":"Divulgations protégées"},{"en":"Survival after employment","fr":"Survie après l’emploi"}]'::jsonb, '<h1 class="center">Confidentiality Agreement</h1>
<p>This Confidentiality Agreement (the <strong>Agreement</strong>) is made on <strong><span class="mf">{{agreement_date}}</span></strong>.</p>
<h2>Between</h2>
<p><strong><span class="mf">{{employer_legal_name}}</span></strong>, with its principal office at <strong><span class="mf">{{employer_address}}</span></strong> (the <strong>Company</strong>),</p>
<p>— and —</p>
<p><strong><span class="mf">{{recipient_name}}</span></strong>, of <strong><span class="mf">{{recipient_address}}</span></strong> (the <strong>Recipient</strong>).</p>
<h2>Why we''re asking you to sign this</h2>
<p>In the course of your relationship with us — as an employee, contractor, advisor or counterparty — you will learn things about our business, our people, our customers and our technology that aren''t public. Those things are how we compete, how we serve our customers, and sometimes how we keep other people''s information safe. This Agreement is about protecting all of that, and about being clear with you about what we''re asking.</p>
<h2>1. What counts as Confidential Information</h2>
<p><strong>Confidential Information</strong> means any non-public information, in any form (written, oral, electronic, visual or any other), that the Company discloses to the Recipient or that the Recipient learns from the Company, whether before or after the date of this Agreement, including:</p>
<ul><li>Business plans, strategies, forecasts, pricing and financial information.</li><li>Customer, supplier and partner information, contracts, and communications.</li><li>Product designs, source code, algorithms, architectures, research and development.</li><li>Personnel information, including compensation, performance and personal information protected under applicable privacy law.</li><li>Any information the Company marks as confidential, or that a reasonable person would understand to be confidential in the circumstances.</li></ul>
<p>Confidential Information does not include information that: (a) was already lawfully in the Recipient''s possession without a duty of confidentiality before disclosure; (b) is or becomes publicly available through no fault of the Recipient; (c) is independently developed by the Recipient without using the Confidential Information; or (d) is lawfully obtained from a third party who is free to disclose it.</p>
<h2>2. How the Recipient must treat it</h2>
<p>The Recipient will:</p>
<ul><li>Use the Confidential Information only for the purpose described in section 3.</li><li>Keep it secret — with at least the same care the Recipient uses for their own confidential information, and in any event no less than a reasonable standard of care.</li><li>Not disclose it to any third party without the Company''s prior written consent, except to the Recipient''s legal, tax or financial advisors who are bound by equivalent confidentiality obligations.</li><li>Not copy, reverse engineer, decompile or disassemble it, except as necessary for the Purpose.</li><li>Protect Confidential Information with reasonable administrative, technical and physical safeguards.</li></ul>
<h2>3. Purpose</h2>
<p>The Recipient may use Confidential Information only for <strong><span class="mf">{{purpose_description}}</span></strong> (the <strong>Purpose</strong>). Any other use requires the Company''s prior written consent.</p>
<h2>4. Required disclosures</h2>
<p>If the Recipient is required by law, court order, or a regulator to disclose any Confidential Information, the Recipient will (where legally permitted) promptly notify the Company so that the Company may seek a protective order or other appropriate remedy, and will cooperate reasonably with any such effort. The Recipient will disclose only the portion of Confidential Information that is legally required.</p>
<p>Nothing in this Agreement prevents the Recipient from making a protected disclosure to a regulator, law-enforcement agency or court, participating in a human-rights, whistleblower or similar complaint, or discussing wages or working conditions with coworkers as permitted by law.</p>
<h2>5. Personal information and privacy</h2>
<p>If Confidential Information includes personal information, the Recipient will handle it in accordance with <strong>PIPEDA (federal baseline); Ontario has no private-sector privacy statute — federal PIPEDA fills the gap</strong>. The Recipient will promptly notify the Company of any privacy incident or suspected incident.</p>
<h2>6. Term</h2>
<p>The Recipient''s obligations under this Agreement begin on the date above and continue for <strong><span class="mf">{{confidentiality_term_years}}</span></strong> years after the end of the Recipient''s relationship with the Company, or indefinitely for information that is a trade secret. Obligations under privacy law continue for as long as that law requires.</p>
<h2>7. Return or destruction</h2>
<p>At the Company''s request, and in any event within <strong><span class="mf">{{return_period_days}}</span></strong> days after the end of the Recipient''s relationship with the Company, the Recipient will return or (at the Company''s option) securely destroy all Confidential Information, including copies, notes and derivative works. The Recipient may retain one archival copy in encrypted form solely to comply with legal or regulatory retention obligations; that copy remains subject to this Agreement for as long as it is retained.</p>
<h2>8. No ownership transfer</h2>
<p>All Confidential Information remains the property of the Company. Nothing in this Agreement grants the Recipient any licence or other right to the Confidential Information, except the limited right to use it for the Purpose.</p>
<h2>9. No warranty</h2>
<p>The Company provides the Confidential Information "as is" and makes no representation or warranty about its accuracy or completeness, except as expressly set out in another written agreement between the Parties.</p>
<h2>10. Remedies</h2>
<p>The Parties acknowledge that money damages alone may not be enough to remedy a breach of this Agreement, and that the Company may seek injunctive relief in addition to any other legal or equitable remedy, without having to prove actual damages and without being required to post a bond (where permitted by law).</p>
<h2>11. General</h2>
<p>This Agreement is governed by the laws of the Province of <strong>Province of Ontario</strong>. If any part of this Agreement is found unenforceable, the rest continues in full force. This Agreement is the entire agreement between the Parties concerning its subject matter, and may only be amended in writing signed by both Parties. The Recipient confirms that the Recipient has had the opportunity to obtain independent legal advice before signing.</p>
<p>By signing below, the Parties confirm they have read and accept the terms of this Agreement.</p>
<div class="spacer">&nbsp;</div>
<table class="sig"><tr>
        <td>
          <div class="sig-line">______________________________________</div>
          <div class="sig-under">Signature — <span class="mf">{{employer_signer_name}}</span></div>
          <div class="sig-under"><span class="mf">{{employer_signer_title}}</span></div>
          <div class="sig-under">Date: <span class="mf">{{employer_signature_date}}</span></div>
          <div class="sig-label">COMPANY</div>
        </td>
        <td>
          <div class="sig-line">______________________________________</div>
          <div class="sig-under">Signature — <span class="mf">{{recipient_name}}</span></div>
          <div class="sig-under"><span class="mf">{{recipient_title}}</span></div>
          <div class="sig-under">Date: <span class="mf">{{employee_signature_date}}</span></div>
          <div class="sig-label">RECIPIENT</div>
        </td></tr></table>', '2026-02-15', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t06', 'discipline', 'written_warning', 'T06', 'letter', true, 'employee', 'Written warning', 'Avertissement écrit', 'Documents a performance or conduct concern, the expected change, and the consequence if it continues.', 'Documente une préoccupation de rendement ou de conduite, le changement attendu et la conséquence en cas de récidive.', array['ON','QC','FED']::text[], 'medium', 'hr_review_required', false, 6, 52, '2026-02-20', '2026-05-20');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t06_v2', 'tpl_t06', 2, '[{"id":"employee_name","section":{"en":"Employee","fr":"Employé"},"label":{"en":"Employee full name","fr":"Nom complet de l’employé(e)"},"type":"text","required":true,"placeholder":{"en":"Full name","fr":"Nom complet"}},{"id":"concern","section":{"en":"Concern","fr":"Préoccupation"},"label":{"en":"The concern","fr":"La préoccupation"},"type":"textarea","required":true,"placeholder":{"en":"Describe the specific behaviour or performance issue and when it occurred.","fr":"Décrivez le comportement ou le problème de rendement précis et le moment."}},{"id":"expectation","section":{"en":"Expectation","fr":"Attente"},"label":{"en":"Expected change","fr":"Changement attendu"},"type":"textarea","required":true,"placeholder":{"en":"What specifically must improve, and by when.","fr":"Ce qui doit s’améliorer précisément, et pour quand."}},{"id":"review_date","section":{"en":"Follow-up","fr":"Suivi"},"label":{"en":"Review date","fr":"Date de révision"},"type":"date","required":true}]'::jsonb, '[{"type":"title","text":{"en":"Written Warning","fr":"Avertissement écrit"}},{"type":"meta","text":{"en":"{{org}} · {{today}} · Confidential","fr":"{{org}} · {{today}} · Confidentiel"}},{"type":"para","text":{"en":"This letter is a formal written warning to {{employee_name}} regarding the following concern:","fr":"La présente constitue un avertissement écrit formel à {{employee_name}} concernant la préoccupation suivante :"}},{"type":"clause","text":{"en":"{{concern}}","fr":"{{concern}}"},"n":1,"heading":{"en":"The concern","fr":"La préoccupation"}},{"type":"clause","text":{"en":"{{expectation}} We will review progress together on {{review_date}}. Support is available to help you meet this expectation.","fr":"{{expectation}} Nous réviserons les progrès ensemble le {{review_date}}. Du soutien est disponible pour vous aider à atteindre cette attente."},"n":2,"heading":{"en":"What we expect","fr":"Nos attentes"}},{"type":"para","text":{"en":"Failure to meet the expectation may lead to further action, up to and including termination. You may add your response below.","fr":"Le non-respect de l’attente peut mener à d’autres mesures, pouvant aller jusqu’à la cessation d’emploi. Vous pouvez ajouter votre réponse ci-dessous."}},{"type":"clause","text":{"en":"This workplace is unionized: the collective agreement and its grievance procedure govern this process, and this document must follow the negotiated steps and timelines.","fr":"Ce milieu de travail est syndiqué : la convention collective et sa procédure de grief régissent ce processus, et le présent document doit suivre les étapes et les délais négociés."},"heading":{"en":"Collective agreement","fr":"Convention collective"},"when":{"union":true}},{"type":"sig","roles":[{"en":"Employer representative","fr":"Représentant de l’employeur"},{"en":"Employee","fr":"Employé(e)"}]},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"Progressive-discipline principles","fr":"Principes de discipline progressive"},{"en":"Human Rights Code — accommodation before discipline","fr":"Code des droits de la personne — adaptation avant discipline"}]'::jsonb, '{"ON":{"en":"Rule out a disability or accommodation need before disciplining for performance.","fr":"Écarter un besoin d’adaptation ou un handicap avant de discipliner pour le rendement."},"QC":{"en":"Keep records; the CNESST and tribunals expect a fair, documented process.","fr":"Conserver les dossiers; la CNESST et les tribunaux attendent un processus équitable et documenté."},"FED":{"en":"Document steps carefully — unjust-dismissal review considers the discipline record.","fr":"Documenter les étapes — l’examen pour congédiement injuste tient compte du dossier disciplinaire."}}'::jsonb, '[{"en":"The concern","fr":"La préoccupation"},{"en":"Expectation & standard","fr":"Attente et norme"},{"en":"Support offered","fr":"Soutien offert"},{"en":"Consequence if unresolved","fr":"Conséquence si non résolu"},{"en":"Employee response","fr":"Réponse de l’employé"}]'::jsonb, '<p class="date"><span class="mf">{{document_date}}</span></p>
<address><span class="mf">{{employee_name}}</span><br><span class="mf">{{employee_address_line_1}}</span><br><span class="mf">{{employee_address_line_2}}</span></address>
<p class="re"><strong>Re:</strong> Written warning — <span class="mf">{{warning_subject}}</span></p>
<p>Dear <span class="mf">{{employee_first_name}}</span>,</p>
<p>The purpose of this letter is to formally document a concern we have discussed with you and to confirm the expectations going forward. A written warning is a serious step, but it is not the end of the road — it is an honest, early conversation so we can course-correct together.</p>
<h2>1. Summary of the concern</h2>
<p>On <strong><span class="mf">{{incident_date}}</span></strong>, the following occurred: <strong><span class="mf">{{incident_description}}</span></strong>. This was discussed with you on <strong><span class="mf">{{verbal_warning_date}}</span></strong> by <strong><span class="mf">{{verbal_warning_by}}</span></strong>. Despite that conversation, the concern has not been fully resolved.</p>
<h2>2. Why this is a concern</h2>
<p>The behaviour described above is inconsistent with <strong><span class="mf">{{policy_or_expectation}}</span></strong>. We are raising it because it matters to us, to your colleagues, and to our customers — and because we believe you can meet the expectation with the right support.</p>
<h2>3. What we expect going forward</h2>
<p>Effective immediately, we expect you to:</p>
<ul><li><strong><span class="mf">{{expectation_1}}</span></strong></li><li><strong><span class="mf">{{expectation_2}}</span></strong></li><li><strong><span class="mf">{{expectation_3}}</span></strong></li></ul>
<p>We will check in on <strong><span class="mf">{{checkin_date}}</span></strong> to discuss how things are going. In the meantime, your manager <strong><span class="mf">{{manager_name}}</span></strong> is available to support you — please reach out whenever you need to.</p>
<h2>4. Support available to you</h2>
<p>If anything outside of work is making it harder to meet these expectations — your health, a family situation, anything protected under human rights legislation — please tell us. You are entitled to reasonable accommodation up to the point of undue hardship, in accordance with the *Meiorin* test (*British Columbia (PSERC) v. BCGSEU*, [1999] 3 S.C.R. 3) and applicable human rights legislation. You can also access our Employee and Family Assistance Program at <strong><span class="mf">{{eap_contact}}</span></strong> for confidential counselling and support.</p>
<h2>5. Consequences if the concern continues</h2>
<p>If the concern is not resolved after this warning, further steps under our progressive discipline process may follow, up to and including termination of your employment for just cause. Any decision to move to termination for cause would be made contextually, as required by *McKinley v. BC Tel*, 2001 SCC 38, considering the nature and circumstances of the behaviour and giving you a fair opportunity to respond. Nothing in this letter limits your entitlements under the employment standards legislation that applies to your province (for example, the <strong>Employment Standards Act, 2000</strong>, S.O. 2000, c. 41 in Ontario).</p>
<h2>6. Your right to respond</h2>
<p>You are welcome to provide a written response to this warning, and to include any context we may have missed. If you do, we will add your response to your employment file. You have the right to be treated fairly throughout this process and to have any concerns about this warning escalated to <strong><span class="mf">{{hr_contact_name}}</span></strong>.</p>
<h2>7. How long this stays active</h2>
<p>This warning will remain active on your file for <strong><span class="mf">{{warning_active_period}}</span></strong>. If the concern is resolved and does not recur during that period, the warning is no longer considered in future decisions, except to the extent relevant to a pattern.</p>
<p>We want to be very clear: this letter is not a reflection of your value as a person or a teammate. It is an honest attempt to help us both move forward. We are here to support you.</p>
<p class="signoff-closing">With respect,</p><p class="signoff-name"><span class="mf">{{employer_signer_name}}</span></p><p class="signoff-line"><span class="mf">{{employer_signer_title}}</span></p><p class="signoff-line"><span class="mf">{{employer_legal_name}}</span></p>
<div class="spacer">&nbsp;</div>
<p><strong>Acknowledgement of receipt.</strong> My signature below indicates that I have received and read this warning. It does not mean I agree with every detail — I may provide a written response. I understand I can contact <strong><span class="mf">{{hr_contact_name}}</span></strong> with any questions.</p>
<table class="sig"><tr>
        <td>
          <div class="sig-line">______________________________________</div>
          <div class="sig-under">Signature — <span class="mf">{{employer_signer_name}}</span></div>
          <div class="sig-under"><span class="mf">{{employer_signer_title}}</span></div>
          <div class="sig-under">Date: <span class="mf">{{employer_signature_date}}</span></div>
          <div class="sig-label">EMPLOYER</div>
        </td>
        <td>
          <div class="sig-line">______________________________________</div>
          <div class="sig-under">Signature — <span class="mf">{{employee_name}}</span></div>
          <div class="sig-under"><span class="mf">{{employee_position}}</span></div>
          <div class="sig-under">Date: <span class="mf">{{employee_signature_date}}</span></div>
          <div class="sig-label">EMPLOYEE — RECEIVED</div>
        </td></tr></table>', '2026-02-20', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t07', 'hiring', 'contractor_agreement', 'T07', 'agreement', true, 'external', 'Independent contractor agreement', 'Contrat de travailleur autonome', 'Engages a contractor, not an employee. Misclassification is a leading liability — the real relationship decides status.', 'Engage un travailleur autonome, non un employé. La mauvaise classification est une source majeure de responsabilité.', array['ON','QC','FED']::text[], 'high', 'lawyer_review_recommended', true, 10, 22, '2026-02-15', '2026-06-20');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t07_v3', 'tpl_t07', 3, '[{"id":"contractor_name","section":{"en":"Party","fr":"Partie"},"label":{"en":"Contractor / business name","fr":"Nom du travailleur / de l’entreprise"},"type":"text","required":true,"placeholder":{"en":"e.g. Rivard Consulting Inc.","fr":"p. ex. Rivard Conseil inc."}},{"id":"services","section":{"en":"Services","fr":"Services"},"label":{"en":"Services provided","fr":"Services fournis"},"type":"textarea","required":true,"placeholder":{"en":"Describe the deliverables and scope.","fr":"Décrivez les livrables et la portée."}},{"id":"fee_basis","section":{"en":"Fees","fr":"Honoraires"},"label":{"en":"Fee & basis","fr":"Honoraires et base"},"type":"text","required":true,"placeholder":{"en":"e.g. $95/hr, invoiced monthly","fr":"p. ex. 95 $/h, facturé mensuellement"}},{"id":"engagement_length","section":{"en":"Term","fr":"Durée"},"label":{"en":"Engagement length","fr":"Durée de l’engagement"},"type":"text","required":true,"placeholder":{"en":"e.g. 6 months","fr":"p. ex. 6 mois"}}]'::jsonb, '[{"type":"title","text":{"en":"Independent Contractor Agreement","fr":"Contrat de travailleur autonome"}},{"type":"para","text":{"en":"Between {{org}} and {{contractor_name}}, effective {{today}}.","fr":"Entre {{org}} et {{contractor_name}}, en vigueur le {{today}}."}},{"type":"clause","text":{"en":"The Contractor is an independent business, controls how the work is done, uses its own tools, and is not an employee of {{org}}. The Contractor is responsible for its own taxes, remittances, and insurance.","fr":"Le Contractant est une entreprise indépendante, contrôle l’exécution du travail, utilise ses propres outils et n’est pas un employé de {{org}}. Il est responsable de ses impôts, remises et assurances."},"n":1,"heading":{"en":"Independent status","fr":"Statut indépendant"}},{"type":"clause","text":{"en":"Services: {{services}}. Fees: {{fee_basis}}, over an engagement of {{engagement_length}}.","fr":"Services : {{services}}. Honoraires : {{fee_basis}}, sur un engagement de {{engagement_length}}."},"n":2,"heading":{"en":"Services & fees","fr":"Services et honoraires"}},{"type":"sig","roles":[{"en":"Employer representative","fr":"Représentant de l’employeur"},{"en":"Employee","fr":"Employé(e)"}]},{"type":"note","text":{"en":"Higher-risk document. Lawyer review is recommended before this is sent or signed. Dutiva does not provide legal advice.","fr":"Document à risque élevé. Une révision juridique est recommandée avant l’envoi ou la signature. Dutiva ne fournit pas de conseils juridiques."},"tone":"risk"}]'::jsonb, '[{"en":"CRA control / integration tests","fr":"Tests de contrôle / intégration de l’ARC"},{"en":"ESA, 2000 (if reclassified)","fr":"LNE, 2000 (si requalifié)"},{"en":"Dependent-contractor case law","fr":"Jurisprudence sur l’entrepreneur dépendant"}]'::jsonb, '{"ON":{"en":"A contractor treated like an employee can be reclassified, triggering ESA entitlements and CRA remittances.","fr":"Un autonome traité comme employé peut être requalifié, entraînant droits LNE et remises à l’ARC."},"QC":{"en":"Revenu Québec and the CNESST apply their own tests; a dependent contractor may gain protections.","fr":"Revenu Québec et la CNESST appliquent leurs propres tests; un entrepreneur dépendant peut obtenir des protections."},"FED":{"en":"Reclassification can expose the payer to source-deduction and Code liabilities.","fr":"Une requalification peut exposer le payeur aux retenues à la source et aux responsabilités du Code."}}'::jsonb, '[{"en":"Independent status","fr":"Statut indépendant"},{"en":"Services & deliverables","fr":"Services et livrables"},{"en":"Fees & invoicing","fr":"Honoraires et facturation"},{"en":"Own tools & risk","fr":"Outils et risque propres"},{"en":"IP assignment","fr":"Cession de PI"},{"en":"No employee benefits","fr":"Aucun avantage d’employé"},{"en":"Term & termination","fr":"Durée et cessation"}]'::jsonb, '<h1 class="center">Independent Contractor Agreement</h1>
<p>This Independent Contractor Agreement (the <strong>Agreement</strong>) is made on <strong><span class="mf">{{agreement_date}}</span></strong>.</p>
<h2>Between</h2>
<p><strong><span class="mf">{{employer_legal_name}}</span></strong>, with its principal office at <strong><span class="mf">{{employer_address}}</span></strong> (the <strong>Client</strong>),</p>
<p>— and —</p>
<p><strong><span class="mf">{{contractor_legal_name}}</span></strong>, of <strong><span class="mf">{{contractor_address}}</span></strong> (the <strong>Contractor</strong>).</p>
<h2>Framing</h2>
<p>This Agreement sets out the terms under which the Contractor will provide services to the Client. We want to be upfront about one important thing: this is a business-to-business relationship, not employment. We have drafted it that way intentionally, and we expect both Parties to behave consistently with that. If how we actually work together ever starts to look more like employment — because of direction, control, integration, or any of the factors in *671122 Ontario Ltd. v. Sagaz Industries Canada Inc.*, 2001 SCC 59 — we will have a conversation and, if necessary, restructure the relationship rather than leave it misclassified.</p>
<h2>1. Services</h2>
<p>The Contractor will provide the services described in Schedule A — Statement of Work (the <strong>Services</strong>). The Contractor decides, within reason, how and where to perform the Services, subject only to any schedule, deliverables, quality standards or security requirements set out in Schedule A.</p>
<h2>2. Independent status</h2>
<p>The Contractor is an independent business, not an employee, partner, agent or joint venturer of the Client. The Contractor:</p>
<ul><li>is free to accept work from other clients, subject only to the confidentiality and conflict-of-interest provisions in this Agreement;</li><li>provides its own tools, equipment and workspace, except any items the Client specifically agrees to supply in Schedule A;</li><li>is responsible for its own taxes, CPP/QPP, EI (if applicable), HST/GST/QST registration and remittance, and its own insurance (including commercial general liability and, where applicable, professional liability);</li><li>may subcontract the Services only with the Client''s prior written consent, and remains fully responsible for its subcontractors;</li><li>is not entitled to employee benefits, vacation pay, overtime, statutory holiday pay, or termination or severance entitlements under the employment standards legislation that applies to the Client.</li></ul>
<p>Nothing in this Agreement makes the Contractor a "dependent contractor" under the line of authority that includes *McKee v. Reid''s Heritage Homes Ltd.*, 2009 ONCA 916. The Parties have structured the relationship deliberately to avoid that classification.</p>
<h2>3. Fees and expenses</h2>
<p>The Client will pay the Contractor <strong><span class="mf">{{contractor_fee_description}}</span></strong>, plus applicable HST/GST/QST, against valid invoices submitted <strong><span class="mf">{{invoice_frequency}}</span></strong> to <strong><span class="mf">{{ap_contact_email}}</span></strong>. Undisputed invoices are payable within <strong><span class="mf">{{payment_terms_days}}</span></strong> days. Reasonable, pre-approved expenses are reimbursable upon production of receipts.</p>
<h2>4. Term and termination</h2>
<p>This Agreement begins on <strong><span class="mf">{{services_start_date}}</span></strong> and continues until <strong><span class="mf">{{services_end_date}}</span></strong>, unless ended earlier in accordance with this section. Either Party may end this Agreement on <strong><span class="mf">{{contractor_notice_days}}</span></strong> days'' written notice, with or without reason. Either Party may end this Agreement immediately on written notice if the other Party materially breaches the Agreement and fails to cure the breach within <strong><span class="mf">{{cure_period_days}}</span></strong> days, or becomes insolvent. On termination, the Client will pay for Services satisfactorily completed up to the termination date.</p>
<h2>5. Confidentiality</h2>
<p>The Contractor will keep the Client''s Confidential Information confidential during and after the term of this Agreement, on the terms of our standard Confidentiality Agreement, which is incorporated by reference. Confidential Information is broadly defined and includes client, personnel, technology and business information. This obligation survives the end of this Agreement.</p>
<h2>6. Intellectual property</h2>
<p>All deliverables created by the Contractor specifically for the Client under this Agreement (the <strong>Deliverables</strong>) are a work made for hire to the fullest extent permitted by law, and otherwise are assigned to the Client upon creation, including copyright and all other IP rights. The Contractor waives all moral rights in the Deliverables to the extent permitted by law. The Contractor retains ownership of any pre-existing materials, tools and know-how used to create the Deliverables, and grants the Client a perpetual, worldwide, royalty-free licence to use those embedded materials as part of the Deliverables.</p>
<h2>7. Privacy and data</h2>
<p>If the Services involve personal information, the Contractor will handle it in accordance with the <strong>Personal Information Protection and Electronic Documents Act</strong>, S.C. 2000, c. 5 and any applicable provincial privacy law (including Québec''s Law 25 — <strong>An Act to modernize legislative provisions as regards the protection of personal information</strong>, S.Q. 2021, c. 25), use it only for the Services, protect it with reasonable safeguards, and return or destroy it at the end of the Agreement. The Contractor will promptly report any privacy incident to the Client.</p>
<h2>8. Representations and warranties</h2>
<p>The Contractor represents and warrants that: (a) it has the right and authority to enter into this Agreement; (b) it will perform the Services in a professional, workmanlike manner consistent with industry standards; (c) the Deliverables will not infringe any third-party IP rights; and (d) the Contractor will comply with all applicable laws, including health and safety, anti-bribery, anti-spam and human rights laws.</p>
<h2>9. Indemnity and limitation of liability</h2>
<p>Each Party will indemnify the other for damages arising from the indemnifying Party''s breach of this Agreement, gross negligence or wilful misconduct. Neither Party is liable to the other for indirect, consequential, special or punitive damages, and each Party''s total liability for direct damages under this Agreement is capped at the fees paid or payable under this Agreement in the <strong><span class="mf">{{liability_cap_period}}</span></strong> preceding the event giving rise to the claim. This cap does not apply to the Contractor''s confidentiality, IP assignment, privacy, or indemnity obligations, or to a Party''s gross negligence or wilful misconduct.</p>
<h2>10. General</h2>
<p>This Agreement is governed by the laws of the Province of <strong>Province of Ontario</strong>. It is the entire agreement between the Parties about its subject matter and replaces any earlier agreement. It may only be amended in writing signed by both Parties. If any part is found unenforceable, the rest continues in full force. Neither Party may assign this Agreement without the other''s prior written consent, except to a successor of all or substantially all of its business. The Contractor confirms that it has had the opportunity to obtain independent legal and tax advice before signing.</p>
<p>By signing below, the Parties confirm they have read and accept the terms of this Agreement.</p>
<div class="spacer">&nbsp;</div>
<table class="sig"><tr>
        <td>
          <div class="sig-line">______________________________________</div>
          <div class="sig-under">Signature — <span class="mf">{{employer_signer_name}}</span></div>
          <div class="sig-under"><span class="mf">{{employer_signer_title}}</span></div>
          <div class="sig-under">Date: <span class="mf">{{employer_signature_date}}</span></div>
          <div class="sig-label">CLIENT</div>
        </td>
        <td>
          <div class="sig-line">______________________________________</div>
          <div class="sig-under">Signature — <span class="mf">{{contractor_legal_name}}</span></div>
          <div class="sig-under"><span class="mf">{{contractor_signer_title}}</span></div>
          <div class="sig-under">Date: <span class="mf">{{employee_signature_date}}</span></div>
          <div class="sig-label">CONTRACTOR</div>
        </td></tr></table>', '2026-02-15', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t08', 'agreements', 'restrictive_covenants', 'T08', 'agreement', true, 'employee', 'Restrictive covenants agreement', 'Entente de clauses restrictives', 'Non-solicitation and (where lawful) non-competition terms. In Ontario, employee non-competes are largely banned.', 'Clauses de non-sollicitation et (là où c’est permis) de non-concurrence. En Ontario, les non-concurrences sont largement interdites.', array['ON','QC','FED']::text[], 'high', 'lawyer_review_recommended', true, 9, 14, '2026-01-25', '2026-06-10');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t08_v2', 'tpl_t08', 2, '[{"id":"employee_name","section":{"en":"Party","fr":"Partie"},"label":{"en":"Employee full name","fr":"Nom complet de l’employé(e)"},"type":"text","required":true,"placeholder":{"en":"Full legal name","fr":"Nom légal complet"}},{"id":"covenant_scope","section":{"en":"Scope","fr":"Portée"},"label":{"en":"Covenants to include","fr":"Clauses à inclure"},"type":"select","required":true,"options":[{"value":"non-solicitation only","label":{"en":"Non-solicitation only","fr":"Non-sollicitation seulement"}},{"value":"non-solicitation + non-compete","label":{"en":"Non-solicitation + non-compete","fr":"Non-sollicitation + non-concurrence"}}]},{"id":"duration_months","section":{"en":"Scope","fr":"Portée"},"label":{"en":"Duration (months)","fr":"Durée (mois)"},"type":"number","required":true,"placeholder":{"en":"12","fr":"12"}}]'::jsonb, '[{"type":"title","text":{"en":"Restrictive Covenants Agreement","fr":"Entente de clauses restrictives"}},{"type":"para","text":{"en":"Between {{org}} and {{employee_name}}. Covenants included: {{covenant_scope}}, for {{duration_months}} months.","fr":"Entre {{org}} et {{employee_name}}. Clauses incluses : {{covenant_scope}}, pour {{duration_months}} mois."}},{"type":"clause","text":{"en":"Each covenant is limited to what is reasonable in duration, territory, and activity, and necessary to protect legitimate business interests. Overly broad terms may be unenforceable.","fr":"Chaque clause est limitée au raisonnable en durée, territoire et activité, et nécessaire pour protéger des intérêts légitimes. Des clauses trop larges peuvent être inexécutoires."},"n":1,"heading":{"en":"Reasonableness","fr":"Raisonnabilité"}},{"type":"clause","text":{"en":"In Ontario, employee non-compete agreements are prohibited under the ESA except in narrow cases; where prohibited, only non-solicitation applies.","fr":"En Ontario, les non-concurrences pour employés sont interdites par la LNE sauf cas restreints; là où c’est interdit, seule la non-sollicitation s’applique."},"n":2,"heading":{"en":"Ontario note","fr":"Note Ontario"}},{"type":"sig","roles":[{"en":"Employer representative","fr":"Représentant de l’employeur"},{"en":"Employee","fr":"Employé(e)"}]},{"type":"note","text":{"en":"Higher-risk document. Lawyer review is recommended before this is sent or signed. Dutiva does not provide legal advice.","fr":"Document à risque élevé. Une révision juridique est recommandée avant l’envoi ou la signature. Dutiva ne fournit pas de conseils juridiques."},"tone":"risk"}]'::jsonb, '[{"en":"ESA, 2000 ss. 67.1–67.2 — non-compete prohibition (ON)","fr":"LNE, 2000 art. 67.1–67.2 — interdiction de non-concurrence (ON)"},{"en":"Common-law reasonableness test","fr":"Test de raisonnabilité de common law"},{"en":"Civil Code of Québec","fr":"Code civil du Québec"}]'::jsonb, '{"ON":{"en":"Employee non-compete agreements are prohibited under the ESA except in narrow cases (e.g. sale of a business). Non-solicitation may still be enforceable.","fr":"Les non-concurrences pour employés sont interdites par la LNE sauf cas restreints (p. ex. vente d’entreprise). La non-sollicitation peut demeurer exécutoire."},"QC":{"en":"The Civil Code limits non-competes to what is reasonable in time, place, and activity, and the employer bears the burden.","fr":"Le Code civil limite les non-concurrences au raisonnable en temps, lieu et activité; le fardeau incombe à l’employeur."},"FED":{"en":"Provincial rules of the employee’s province generally apply to covenant enforceability.","fr":"Les règles provinciales de la province de l’employé s’appliquent généralement."}}'::jsonb, '[{"en":"Non-solicitation of clients","fr":"Non-sollicitation des clients"},{"en":"Non-solicitation of staff","fr":"Non-sollicitation du personnel"},{"en":"Non-competition (if lawful)","fr":"Non-concurrence (si permis)"},{"en":"Reasonableness limits","fr":"Limites de raisonnabilité"},{"en":"Severability","fr":"Divisibilité"}]'::jsonb, '<h1 class="center">Restrictive Covenants Agreement</h1>
<p>This Restrictive Covenants Agreement (the <strong>Agreement</strong>) is made on <strong><span class="mf">{{agreement_date}}</span></strong> between <strong><span class="mf">{{employer_legal_name}}</span></strong> (the <strong>Company</strong>) and <strong><span class="mf">{{employee_name}}</span></strong> (the <strong>Employee</strong>).</p>
<h2>Why we''re asking for this</h2>
<p>Your role will put you in contact with our customers, our prospects, our confidential information, and the relationships that make our business work. This Agreement is about protecting those relationships and that information for a reasonable period after you leave — not about preventing you from working. We have drafted these restrictions to be as narrow as they can reasonably be, consistent with *J.G. Collins Insurance Agencies Ltd. v. Elsley*, [1978] 2 S.C.R. 916 and *Shafron v. KRG Insurance Brokers (Western) Inc.*, 2009 SCC 6.</p>
<h2>1. Definitions</h2>
<p>In this Agreement:</p>
<ul><li><strong>Restricted Period</strong> means the <strong><span class="mf">{{restricted_period}}</span></strong> period that begins when your employment with the Company ends, for any reason.</li><li><strong>Restricted Territory</strong> means <strong><span class="mf">{{restricted_territory}}</span></strong>.</li><li><strong>Restricted Business</strong> means the business of <strong><span class="mf">{{restricted_business_description}}</span></strong> as actually carried on by the Company at the time your employment ends.</li><li><strong>Customer</strong> means a person or entity that was a customer of the Company, or an active prospect the Company was actively pursuing, at any time in the <strong><span class="mf">{{customer_lookback}}</span></strong> months before your employment ends, and with whom you had material dealings or about whom you had access to Confidential Information during that period.</li></ul>
<h2>2. Non-solicitation of customers</h2>
<p>During the Restricted Period, you will not, directly or indirectly, solicit any Customer for the purpose of providing products or services that compete with the Restricted Business. This clause is about solicitation — it does not prevent you from responding to a Customer who freely approaches you without any inducement from you.</p>
<h2>3. Non-dealing (limited)</h2>
<p>During the Restricted Period, you will not, directly or indirectly, accept the business of any Customer in connection with products or services that compete with the Restricted Business, to the extent that doing so would involve a material use of Confidential Information you learned at the Company. This restriction is limited to what is reasonably necessary to protect the Company''s legitimate interests in Confidential Information and customer goodwill.</p>
<h2>4. Non-solicitation of employees and contractors</h2>
<p>During the Restricted Period, you will not, directly or indirectly, solicit or induce any employee or active contractor of the Company with whom you worked during the last <strong><span class="mf">{{employee_lookback}}</span></strong> months of your employment to leave the Company. Receiving an application from someone who responds to a general advertisement (not directed at Company personnel) is not a breach of this clause.</p>
<h2>5. Non-competition (limited, executive/sale-of-business only)</h2>
<p><strong>This section only applies in two specific situations:</strong></p>
<ul><li>(a) <strong>Executive carve-out (Ontario).</strong> If you are an "executive" within the meaning of s. 67.2(4) of the <strong>Employment Standards Act, 2000</strong>, S.O. 2000, c. 41 (meaning any of: chief executive officer, president, chief administrative officer, chief operating officer, chief financial officer, chief information officer, chief legal officer, chief human resources officer, chief corporate development officer, or holds any other chief executive position) this Agreement includes the non-competition provisions set out in Schedule A, and you have been told so in writing at the time this Agreement was signed; or</li><li>(b) <strong>Sale-of-business exception (Ontario).</strong> If this Agreement is entered into in connection with the sale of a business or a part of a business within the meaning of s. 67.2(3) of the <strong>Employment Standards Act, 2000</strong>, and you are a seller or former owner of that business.</li></ul>
<p><strong>For every other employee in Ontario, this Agreement does not contain a non-compete.</strong> Ontario''s s. 67.2 prohibition on non-competes applies in full, and any attempted non-compete in this Agreement with respect to a non-executive, non-sale-of-business employee in Ontario is void.</p>
<p>In provinces outside Ontario, a separate non-competition schedule may apply only if expressly attached and identified as applying to you, and only to the minimum extent reasonable to protect legitimate business interests (*Elsley*, *Shafron*).</p>
<h2>6. Confidentiality</h2>
<p>Your confidentiality obligations, including those set out in your employment agreement and any separate confidentiality agreement, continue after your employment ends and are not limited by the Restricted Period. Confidentiality obligations do not prevent you from making a protected disclosure to a regulator or law-enforcement agency, participating in a human-rights or whistleblower complaint, or discussing your wages and working conditions with others as permitted by law.</p>
<h2>7. Reasonableness and severability</h2>
<p>You acknowledge that: (a) the Company has a legitimate proprietary interest in the Confidential Information, Customer relationships and goodwill that these covenants protect; (b) the Restricted Period, Restricted Territory and Restricted Business have been tailored to that interest and are reasonable; and (c) you have had the opportunity to obtain independent legal advice before signing. If a court finds any covenant to be broader than is reasonable, the Parties intend that the covenant be enforced to the maximum extent permitted by law. If that is not possible, the unenforceable covenant is severed and the rest of the Agreement continues in full force.</p>
<h2>8. Remedies</h2>
<p>You agree that money damages alone may not be sufficient to remedy a breach of this Agreement, and that the Company may seek injunctive relief in addition to any other legal or equitable remedy, without having to prove actual damages and without being required to post a bond (where permitted by law). Nothing in this section limits either Party''s other rights and remedies.</p>
<h2>9. Acknowledgement</h2>
<p>You acknowledge that you have read and understood this Agreement, that you had the opportunity to obtain independent legal advice before signing, and that you enter into it freely and voluntarily as a condition of the employment, equity or other consideration identified above.</p>
<h2>10. Governing law</h2>
<p>This Agreement is governed by the laws of the Province of <strong>Province of Ontario</strong> and the laws of Canada that apply in that province.</p>
<p>By signing below, the Parties confirm they have read and accept the terms of this Agreement.</p>
<div class="spacer">&nbsp;</div>
<table class="sig"><tr>
        <td>
          <div class="sig-line">______________________________________</div>
          <div class="sig-under">Signature — <span class="mf">{{employer_signer_name}}</span></div>
          <div class="sig-under"><span class="mf">{{employer_signer_title}}</span></div>
          <div class="sig-under">Date: <span class="mf">{{employer_signature_date}}</span></div>
          <div class="sig-label">COMPANY</div>
        </td>
        <td>
          <div class="sig-line">______________________________________</div>
          <div class="sig-under">Signature — <span class="mf">{{employee_name}}</span></div>
          <div class="sig-under"><span class="mf">{{employee_position}}</span></div>
          <div class="sig-under">Date: <span class="mf">{{employee_signature_date}}</span></div>
          <div class="sig-label">EMPLOYEE</div>
        </td></tr></table>', '2026-01-25', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t09', 'hiring', 'quebec_offer_letter', 'T09', 'letter', true, 'candidate', 'Québec offer letter', 'Lettre d’offre — Québec', 'An offer letter tuned to Québec: French-language default, LSA terms, and Civil Code framing.', 'Une lettre d’offre adaptée au Québec : français par défaut, conditions de la LNT et cadre du Code civil.', array['QC']::text[], 'medium', 'hr_review_required', false, 7, 19, '2026-03-01', '2026-06-12');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t09_v2', 'tpl_t09', 2, '[{"id":"candidate_name","section":{"en":"Candidate","fr":"Candidat"},"label":{"en":"Candidate full name","fr":"Nom complet du candidat"},"type":"text","required":true,"placeholder":{"en":"e.g. Léa Tremblay","fr":"p. ex. Léa Tremblay"}},{"id":"position_title","section":{"en":"Role","fr":"Poste"},"label":{"en":"Position title","fr":"Titre du poste"},"type":"text","required":true,"placeholder":{"en":"e.g. Gestionnaire de comptes","fr":"p. ex. gestionnaire de comptes"}},{"id":"start_date","section":{"en":"Timing","fr":"Échéancier"},"label":{"en":"Start date","fr":"Date d’entrée en fonction"},"type":"date","required":true},{"id":"annual_salary","section":{"en":"Compensation","fr":"Rémunération"},"label":{"en":"Annual salary (CAD)","fr":"Salaire annuel (CAD)"},"type":"text","required":true,"placeholder":{"en":"e.g. 74,000","fr":"p. ex. 74 000"}}]'::jsonb, '[{"type":"title","text":{"en":"Offer of Employment (Québec)","fr":"Offre d’emploi (Québec)"}},{"type":"meta","text":{"en":"{{org}} · {{today}} · Québec","fr":"{{org}} · {{today}} · Québec"}},{"type":"para","text":{"en":"Dear {{candidate_name}}, we offer you the position of {{position_title}}, beginning {{start_date}}, at an annual salary of ${{annual_salary}} CAD.","fr":"Cher/Chère {{candidate_name}}, nous vous offrons le poste de {{position_title}}, débutant le {{start_date}}, au salaire annuel de {{annual_salary}} $ CAD."}},{"type":"clause","text":{"en":"French is the language of work. This offer is provided in French; an English version is available at your express request.","fr":"Le français est la langue de travail. La présente offre est fournie en français; une version anglaise est disponible sur demande expresse."},"n":1,"heading":{"en":"Language of work","fr":"Langue de travail"}},{"type":"clause","text":{"en":"Vacation, notice, and leaves meet or exceed the Act respecting labour standards.","fr":"Les vacances, l’avis et les congés atteignent ou dépassent la Loi sur les normes du travail."},"n":2,"heading":{"en":"Standards (LSA)","fr":"Normes (LNT)"}},{"type":"sig","roles":[{"en":"Employer representative","fr":"Représentant de l’employeur"},{"en":"Employee","fr":"Employé(e)"}]},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"Act respecting labour standards (LSA)","fr":"Loi sur les normes du travail (LNT)"},{"en":"Charter of the French language (Bill 96)","fr":"Charte de la langue française (Loi 96)"},{"en":"Civil Code of Québec","fr":"Code civil du Québec"}]'::jsonb, '{"QC":{"en":"The offer must be available in French; an English version requires the employee’s express wish. LSA minimums apply.","fr":"L’offre doit être disponible en français; une version anglaise requiert la volonté expresse de l’employé. Les minimums de la LNT s’appliquent."}}'::jsonb, '[{"en":"Poste et supérieur","fr":"Poste et supérieur"},{"en":"Date et lieu","fr":"Date et lieu"},{"en":"Rémunération (LNT)","fr":"Rémunération (LNT)"},{"en":"Vacances (LNT)","fr":"Vacances (LNT)"},{"en":"Langue de travail","fr":"Langue de travail"},{"en":"Acceptation","fr":"Acceptation"}]'::jsonb, '<p class="date"><span class="mf">{{document_date}}</span></p>
<address><span class="mf">{{employee_name}}</span><br><span class="mf">{{employee_address_line_1}}</span><br><span class="mf">{{employee_address_line_2}}</span></address>
<p class="re"><strong>Re:</strong> Offer of employment — <span class="mf">{{position_title}}</span> (Québec)</p>
<p>Dear <span class="mf">{{employee_first_name}}</span>,</p>
<blockquote><strong>Important notice about language.</strong> Under the Charter of the French Language, CQLR c C-11, s. 41 (as amended by S.Q. 2022, c. 14, "Bill 96"), the French version of this offer is the binding version of the document. This English version is provided as a courtesy to help you read and understand the offer. If there is any inconsistency between the two, the French text prevails. You have received both versions at the same time and the same terms are offered to you in each language.</blockquote>
<p>We are delighted to offer you the position of <strong><span class="mf">{{position_title}}</span></strong> at <strong><span class="mf">{{employer_legal_name}}</span></strong> (the <strong>Company</strong>), based in the Province of Québec. This letter sets out the main terms of our offer. Please review it carefully and, if everything looks right, sign and return a copy by <strong><span class="mf">{{offer_expiry_date}}</span></strong>.</p>
<h2>1. Your role and start date</h2>
<p>You will report to <strong><span class="mf">{{manager_name}}</span></strong>, <strong><span class="mf">{{manager_title}}</span></strong>, and your primary duties are set out in the attached job description. Your first day will be <strong><span class="mf">{{start_date}}</span></strong>, and you will be based at <strong><span class="mf">{{work_location}}</span></strong>.</p>
<h2>2. Compensation</h2>
<p>Your starting base salary will be <strong><span class="mf">{{annual_base_salary}}</span></strong> per year, paid <strong><span class="mf">{{pay_frequency}}</span></strong> by direct deposit, less statutory deductions. You will also be eligible for <strong><span class="mf">{{variable_comp_description}}</span></strong>, subject to the terms of the applicable plan.</p>
<h2>3. Vacation, holidays and leaves</h2>
<p>You will receive <strong><span class="mf">{{vacation_weeks}}</span></strong> weeks of paid vacation per year, in addition to the statutory holidays prescribed by the <strong>Act respecting Labour Standards</strong>, CQLR c N-1.1 (the <strong>ARLS</strong>). After three years of service, you will be entitled to three weeks or 6% (ARLS art. 68). You are entitled to all leaves of absence prescribed by the ARLS (including parental under the Régime québécois d''assurance parentale, family obligations, sick and personal leave under ARLS art. 79.1, bereavement and domestic-violence leaves), without fear of retaliation.</p>
<h2>4. Overtime and working hours</h2>
<p>Your regular hours will be a maximum of <strong>40 hours per week</strong>. Overtime is payable at 1.5× for hours worked beyond 40 per week (ARLS art. 55). Québec also recognizes a right to refuse overtime in certain family-status situations (ARLS art. 59.0.1).</p>
<h2>5. Benefits and wellbeing</h2>
<p>You will have access to the Company''s <strong><span class="mf">{{benefits_plan_name}}</span></strong> group benefits plan (health, dental, life and disability coverage) starting <strong><span class="mf">{{benefits_start_date}}</span></strong>. You will also have access to our Employee and Family Assistance Program. We believe wellbeing isn''t a perk — it''s part of doing good work.</p>
<h2>6. Probation</h2>
<p>The first <strong><span class="mf">{{probation_length}}</span></strong> of your employment will be a probationary period. During this period, either party may end the employment on the minimum notice required by the ARLS.</p>
<h2>7. Ending the employment</h2>
<p>If employment ends, you will receive at least the notice (or indemnity in lieu) and any other amounts required by the ARLS, including: (a) notice under ARLS art. 82 based on your years of service (1–2 weeks per year for 1–2 years; 2 weeks per year for 3+ years); (b) where applicable, protection against dismissal without just and sufficient cause for employees with two or more years of service under ARLS art. 124; and (c) final wages within 72 hours as required by ARLS art. 82.1. You will be paid for accrued vacation in your final pay.</p>
<h2>8. Confidentiality and intellectual property</h2>
<p>As a condition of employment, you agree to keep the Company''s confidential information confidential both during and after your employment, and that any work product created in the course of your role belongs to the Company. The full terms are in your employment agreement, which will be provided alongside this offer.</p>
<h2>9. Pay equity and language obligations</h2>
<p>The salary offered complies with the Company''s pay equity plan under the Act respecting pay equity, CQLR c E-12.001. This offer is provided in French as the primary version in accordance with the Charter of the French Language, art. 41.</p>
<h2>10. Conditions</h2>
<p>This offer is conditional on: (a) your ability to legally work in Canada; (b) satisfactory completion of the background checks we have described to you; and (c) your signature of the employment agreement and related policies by <strong><span class="mf">{{start_date}}</span></strong>.</p>
<p>If you would like to accept, please sign the French version of this letter and return it to <strong><span class="mf">{{hr_contact_name}}</span></strong> at <strong><span class="mf">{{hr_contact_email}}</span></strong> by <strong><span class="mf">{{offer_expiry_date}}</span></strong>. If you have any questions, please reach out — we are happy to walk through anything with you.</p>
<p class="signoff-closing">Warmly,</p><p class="signoff-name"><span class="mf">{{employer_signer_name}}</span></p><p class="signoff-line"><span class="mf">{{employer_signer_title}}</span></p><p class="signoff-line"><span class="mf">{{employer_legal_name}}</span></p>', '2026-03-01', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t10', 'policies', 'remote_work_policy', 'T10', 'policy', true, 'org', 'Remote & hybrid work policy', 'Politique de télétravail et hybride', 'Sets eligibility, hours, equipment, expenses, data security, and health-and-safety for work away from the office.', 'Définit l’admissibilité, les heures, l’équipement, les dépenses, la sécurité des données et la santé-sécurité hors bureau.', array['ON','QC','FED']::text[], 'low', 'hr_review_required', false, 8, 61, '2026-04-01', '2026-06-25');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t10_v3', 'tpl_t10', 3, '[{"id":"effective_date","section":{"en":"Basics","fr":"Bases"},"label":{"en":"Effective date","fr":"Date d’entrée en vigueur"},"type":"date","required":true},{"id":"model","section":{"en":"Model","fr":"Modèle"},"label":{"en":"Arrangement","fr":"Formule"},"type":"radio","required":true,"options":[{"value":"hybrid","label":{"en":"Hybrid (set office days)","fr":"Hybride (jours fixés)"}},{"value":"fully remote","label":{"en":"Fully remote","fr":"Entièrement à distance"}},{"value":"flexible","label":{"en":"Flexible / case-by-case","fr":"Flexible / cas par cas"}}]},{"id":"office_days","section":{"en":"Model","fr":"Modèle"},"label":{"en":"In-office days/week (if hybrid)","fr":"Jours au bureau/sem. (si hybride)"},"type":"number","required":false,"placeholder":{"en":"2","fr":"2"}},{"id":"core_hours","section":{"en":"Hours","fr":"Heures"},"label":{"en":"Core availability hours","fr":"Heures de disponibilité de base"},"type":"text","required":true,"placeholder":{"en":"e.g. 10:00–15:00 local","fr":"p. ex. 10 h–15 h locale"}},{"id":"equipment","section":{"en":"Equipment","fr":"Équipement"},"label":{"en":"Equipment provided","fr":"Équipement fourni"},"type":"select","required":true,"options":[{"value":"company laptop & essentials","label":{"en":"Company laptop & essentials","fr":"Portable et essentiels fournis"}},{"value":"monthly stipend","label":{"en":"Monthly stipend","fr":"Allocation mensuelle"}},{"value":"bring your own device","label":{"en":"Bring your own device","fr":"Appareil personnel"}}]},{"id":"expenses","section":{"en":"Expenses","fr":"Dépenses"},"label":{"en":"Home-office expenses reimbursed?","fr":"Dépenses de bureau à domicile remboursées?"},"type":"radio","required":true,"options":[{"value":"yes, reasonable expenses","label":{"en":"Yes, reasonable expenses","fr":"Oui, dépenses raisonnables"}},{"value":"no","label":{"en":"No","fr":"Non"}}]}]'::jsonb, '[{"type":"title","text":{"en":"Remote & Hybrid Work Policy","fr":"Politique de télétravail et hybride"}},{"type":"meta","text":{"en":"{{org}} · Effective {{effective_date}} · {{jurisdiction}}","fr":"{{org}} · En vigueur le {{effective_date}} · {{jurisdiction}}"}},{"type":"clause","text":{"en":"{{org}} supports a {{model}} arrangement. Where hybrid, employees attend the office {{office_days}} day(s) per week.","fr":"{{org}} soutient une formule {{model}}. En mode hybride, les employés sont au bureau {{office_days}} jour(s) par semaine."},"n":1,"heading":{"en":"Arrangement","fr":"Formule"}},{"type":"clause","text":{"en":"Core availability is {{core_hours}}. Outside working hours, employees are not expected to respond, consistent with disconnecting-from-work standards.","fr":"La disponibilité de base est {{core_hours}}. Hors des heures, aucune réponse n’est attendue, conformément aux normes sur la déconnexion."},"n":2,"heading":{"en":"Hours & right to disconnect","fr":"Heures et droit à la déconnexion"}},{"type":"clause","text":{"en":"Equipment: {{equipment}}. Reimbursement of reasonable home-office expenses: {{expenses}}.","fr":"Équipement : {{equipment}}. Remboursement des dépenses raisonnables : {{expenses}}."},"n":3,"heading":{"en":"Equipment & expenses","fr":"Équipement et dépenses"}},{"type":"clause","text":{"en":"Employees protect personal and confidential information at home to the same standard as in the office, consistent with PIPEDA and, in Québec, Law 25.","fr":"Les employés protègent à domicile les renseignements au même niveau qu’au bureau, conformément à la LPRPDE et, au Québec, à la Loi 25."},"n":4,"heading":{"en":"Data security","fr":"Sécurité des données"}},{"type":"ack","text":{"en":"I acknowledge I have read and understood this document.","fr":"Je reconnais avoir lu et compris le présent document."}},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"OHSA — remote workspaces","fr":"LSST — espaces distants"},{"en":"ESA, 2000 — hours & disconnecting","fr":"LNE, 2000 — heures et déconnexion"},{"en":"PIPEDA / Law 25 — data at home","fr":"LPRPDE / Loi 25 — données à domicile"}]'::jsonb, '{"ON":{"en":"Employers with 25+ employees must have a written disconnecting-from-work policy under the ESA.","fr":"Les employeurs de 25 employés et plus doivent avoir une politique écrite sur la déconnexion (LNE)."},"QC":{"en":"Reasonable teleworking expenses and CNESST coverage extend to the home workspace.","fr":"Les dépenses raisonnables de télétravail et la couverture CNESST s’étendent au domicile."},"FED":{"en":"Canada Labour Code hours-of-work and right-to-refuse provisions apply to remote work.","fr":"Les dispositions du CCT sur les heures et le droit de refus s’appliquent au télétravail."}}'::jsonb, '[{"en":"Eligibility","fr":"Admissibilité"},{"en":"Hours & availability","fr":"Heures et disponibilité"},{"en":"Right to disconnect","fr":"Droit à la déconnexion"},{"en":"Equipment & expenses","fr":"Équipement et dépenses"},{"en":"Data security","fr":"Sécurité des données"},{"en":"Health & safety at home","fr":"Santé-sécurité à domicile"},{"en":"Ending an arrangement","fr":"Fin d’une entente"}]'::jsonb, '<h1 class="center">Remote Work Policy</h1>
<p class="center"><strong>Effective:</strong> <span class="mf">{{policy_effective_date}}</span> — <strong>Applies to:</strong> <span class="mf">{{policy_scope}}</span></p>
<h2>Why we have this policy</h2>
<p>Where your role allows it, we support working remotely or in a hybrid way. This policy sets out that shared understanding and the legal requirements that apply to remote work in your jurisdiction.</p>
<h2>1. Who is eligible</h2>
<p>Remote work is available where the nature of your role, the security of information, and the needs of your team allow it. Your manager, with HR, decides what arrangement is right for your role.</p>
<h2>2. Types of arrangement</h2>
<p>We support three arrangement types, each documented with your manager: <strong>Onsite</strong>, <strong>Hybrid</strong> (a mix of onsite and remote on an agreed schedule), and <strong>Fully remote</strong> (working from an approved home office or other approved location).</p>
<h2>3. Your remote workspace</h2>
<p>Your remote workspace should be quiet, safe, and confidential. The Company will provide the equipment listed in <span class="mf">{{remote_equipment_list}}</span>; reasonable accommodations for disability-related needs are available on request under the <em>Meiorin</em> standard (<em>British Columbia (PSERC) v. BCGSEU</em>, [1999] 3 S.C.R. 3).</p>
<h2>4. Health and safety at home</h2>
<p>The Company''s health and safety obligations under the Occupational Health and Safety Act, R.S.O. 1990, c. O.1, ss. 32.0.1–32.0.8 extend to remote workspaces. Report any incident or injury that happens while working to <span class="mf">{{hs_contact_name}}</span>.</p>
<h2>5. Working hours and right to disconnect</h2>
<p>Your regular hours of work are the same as they would be onsite. You are expected to be available during core hours of <span class="mf">{{core_hours}}</span>, local time. For employees working in Ontario, this right-to-disconnect policy is provided in accordance with ESA s. 21.1.2 (employers with 25+ employees must have a written policy).</p>
<h2>6. Overtime and accurate timekeeping</h2>
<p>Overtime rules apply to remote work the same as onsite. The overtime threshold in Ontario is 44 hours per week (ESA s. 22). Pre-approval is required before working beyond your regular hours.</p>
<h2>7. Electronic monitoring</h2>
<p>We use the following electronic monitoring practices to protect information security and support business operations: <span class="mf">{{electronic_monitoring_description}}</span>. For employees working in Ontario, this disclosure is provided in accordance with ESA s. 41.1.1 (employers with 25+ employees must have a written electronic monitoring policy).</p>
<h2>8. Information security</h2>
<p>When working remotely, use only Company-approved devices and networks for Company information, do not store Company data on personal cloud storage, and report any suspected security incident to <span class="mf">{{it_security_contact}}</span> immediately.</p>
<h2>9. Expenses and equipment</h2>
<p>Reasonable, pre-approved expenses necessary to perform your role from a remote workspace are reimbursable under our Expense Policy. Company-owned equipment remains the Company''s property at all times and must be returned on request or at the end of employment.</p>
<h2>10. Cross-provincial and relocation considerations</h2>
<p>If you relocate to a different province, you must notify <span class="mf">{{hr_contact_name}}</span> before the move. Employment standards, overtime rules, statutory leaves, and payroll deductions all depend on the province where work is actually performed.</p>
<h2>11. Right to modify the arrangement</h2>
<p>Remote work is not a right — it is an arrangement based on role, performance, and business needs. The Company may change or end a remote arrangement on reasonable notice.</p>
<h2>12. Questions and concerns</h2>
<p>If any part of this policy is unclear, please talk to your manager or <span class="mf">{{hr_contact_name}}</span>.</p>', '2026-04-01', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t11', 'policies', 'vacation_leave_policy', 'T11', 'policy', true, 'org', 'Vacation & leave policy', 'Politique de vacances et de congés', 'Consolidates statutory and company leave — vacation, sick, personal, bereavement, and job-protected leaves.', 'Regroupe les congés légaux et de l’entreprise — vacances, maladie, personnel, deuil et congés protégés.', array['ON','QC','FED']::text[], 'low', 'hr_review_required', false, 7, 57, '2026-01-05', '2026-05-18');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t11_v3', 'tpl_t11', 3, '[{"id":"effective_date","section":{"en":"Basics","fr":"Bases"},"label":{"en":"Effective date","fr":"Date d’entrée en vigueur"},"type":"date","required":true},{"id":"vacation_base","section":{"en":"Vacation","fr":"Vacances"},"label":{"en":"Base vacation entitlement","fr":"Droit de base aux vacances"},"type":"select","required":true,"options":[{"value":"2 weeks","label":{"en":"2 weeks (statutory)","fr":"2 semaines (légal)"}},{"value":"3 weeks","label":{"en":"3 weeks","fr":"3 semaines"}},{"value":"4 weeks","label":{"en":"4 weeks","fr":"4 semaines"}}]},{"id":"sick_days","section":{"en":"Sick","fr":"Maladie"},"label":{"en":"Paid sick / personal days per year","fr":"Jours payés maladie / personnels par an"},"type":"number","required":true,"placeholder":{"en":"5","fr":"5"}}]'::jsonb, '[{"type":"title","text":{"en":"Vacation & Leave Policy","fr":"Politique de vacances et de congés"}},{"type":"meta","text":{"en":"{{org}} · Effective {{effective_date}} · {{jurisdiction}}","fr":"{{org}} · En vigueur le {{effective_date}} · {{jurisdiction}}"}},{"type":"clause","text":{"en":"Employees receive {{vacation_base}} of paid vacation, never below the statutory minimum for {{jurisdiction}}.","fr":"Les employés reçoivent {{vacation_base}} de vacances payées, jamais sous le minimum légal pour {{jurisdiction}}."},"n":1,"heading":{"en":"Vacation","fr":"Vacances"}},{"type":"clause","text":{"en":"{{sick_days}} paid sick/personal days are provided yearly, in addition to all job-protected statutory leaves for {{jurisdiction}}.","fr":"{{sick_days}} jours payés maladie/personnels sont offerts chaque année, en plus de tous les congés légaux protégés pour {{jurisdiction}}."},"n":2,"heading":{"en":"Sick & protected leaves","fr":"Maladie et congés protégés"}},{"type":"ack","text":{"en":"I acknowledge I have read and understood this document.","fr":"Je reconnais avoir lu et compris le présent document."}},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"ESA, 2000 — vacation & leaves","fr":"LNE, 2000 — vacances et congés"},{"en":"Act respecting labour standards","fr":"Loi sur les normes du travail"},{"en":"Canada Labour Code, Part III","fr":"Code canadien du travail, Partie III"}]'::jsonb, '{"ON":{"en":"Vacation is at least 2 weeks (4%), rising to 3 weeks (6%) after 5 years; job-protected leaves are set by the ESA.","fr":"Les vacances sont d’au moins 2 semaines (4 %), portées à 3 semaines (6 %) après 5 ans; congés protégés selon la LNE."},"QC":{"en":"Annual leave and indemnity follow the LSA; company terms may exceed but not reduce them.","fr":"Le congé annuel et l’indemnité suivent la LNT; l’entreprise peut les dépasser mais non les réduire."},"FED":{"en":"Federal minimums include 3 weeks after 5 years and personal/medical leave under the Code.","fr":"Les minimums fédéraux : 3 semaines après 5 ans et congés personnels/médicaux selon le Code."}}'::jsonb, '[{"en":"Vacation accrual","fr":"Accumulation de vacances"},{"en":"Statutory holidays","fr":"Jours fériés"},{"en":"Sick & personal days","fr":"Congés maladie et personnels"},{"en":"Bereavement","fr":"Deuil"},{"en":"Job-protected leaves","fr":"Congés protégés"},{"en":"Requesting leave","fr":"Demander un congé"}]'::jsonb, '<h1 class="center">Vacation and Leave Policy</h1>
<p class="center"><strong>Effective:</strong> <span class="mf">{{policy_effective_date}}</span></p>
<h2>Our philosophy</h2>
<p>Time away isn''t a reward for working hard — it''s part of working well. This policy sets out how vacation and leaves work at <span class="mf">{{employer_legal_name}}</span>, and what the law guarantees you. Where the law requires more than this policy provides, the law controls.</p>
<h2>1. Vacation entitlement</h2>
<p>All regular employees receive <span class="mf">{{vacation_weeks}}</span> weeks of paid vacation per year, meeting or exceeding the minimum required by ESA ss. 33–34. After the applicable threshold, employees receive 3 weeks / 6% after 5 years of service (ESA s. 35.2).</p>
<h2>2. Accrual and timing</h2>
<p>Vacation accrues from your first day of employment. You may take vacation as it accrues, subject to your manager''s approval and the team''s operational needs.</p>
<h2>3. Requesting vacation</h2>
<p>Please request vacation at least <span class="mf">{{vacation_request_notice}}</span> in advance through <span class="mf">{{vacation_request_tool}}</span>.</p>
<h2>4. Carryover and payout on separation</h2>
<p>Carryover of unused vacation is permitted up to <span class="mf">{{carryover_limit}}</span>. On separation from employment, any accrued and unused vacation pay will be paid out in your final wages, as required by ESA ss. 33–42.</p>
<h2>5. Statutory public holidays</h2>
<p>You will be paid for all statutory public holidays recognized in your jurisdiction, at the minimum rate required by law.</p>
<h2>6. Sick leave</h2>
<p>You are entitled to all sick leave required by law, including 3 unpaid sick leave days per year (ESA s. 50.0.1). On top of statutory minimums, the Company offers <span class="mf">{{additional_sick_days}}</span> paid sick days per year.</p>
<h2>7. Pregnancy, parental, adoption and caregiver leaves</h2>
<p>You are entitled to all pregnancy, parental, adoption, family caregiver, and critical illness leaves prescribed by ESA ss. 46–49.1 (pregnancy leave: up to 17 weeks; parental leave: up to 61 weeks). We will not retaliate against you for taking these leaves.</p>
<h2>8. Bereavement, domestic violence, and other protected leaves</h2>
<p>You are entitled to all bereavement, domestic or sexual violence, family responsibility, reservist, organ donor, and other statutory leaves provided by the employment standards legislation that applies to you. Please reach out to <span class="mf">{{hr_contact_name}}</span> as soon as you reasonably can.</p>
<h2>9. Religious accommodation</h2>
<p>We will reasonably accommodate religious observance requests up to the point of undue hardship, in accordance with the Human Rights Code, R.S.O. 1990, c. H.19 and the <em>Meiorin</em> standard.</p>
<h2>10. Communication during time off</h2>
<p>When you are on vacation or leave, we do not expect you to check email, take calls, or respond to messages, consistent with our right-to-disconnect obligations under ESA s. 21.1.2.</p>
<h2>11. Policy review and updates</h2>
<p>This policy is reviewed at least annually. When a legislated minimum changes, the statutory minimum applies automatically. The current version is available at <span class="mf">{{policy_url}}</span>.</p>', '2026-01-05', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t12', 'policies', 'code_of_conduct', 'T12', 'policy', true, 'org', 'Code of conduct', 'Code de conduite', 'The baseline behavioural standard — respect, integrity, conflicts of interest, and how concerns are raised.', 'La norme de comportement de base — respect, intégrité, conflits d’intérêts et façon de soulever des préoccupations.', array['ON','QC','FED']::text[], 'low', 'hr_review_required', false, 7, 96, '2026-01-10', '2026-05-30');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t12_v5', 'tpl_t12', 5, '[{"id":"effective_date","section":{"en":"Basics","fr":"Bases"},"label":{"en":"Effective date","fr":"Date d’entrée en vigueur"},"type":"date","required":true},{"id":"contact","section":{"en":"Reporting","fr":"Signalement"},"label":{"en":"Who concerns go to","fr":"À qui adresser les préoccupations"},"type":"text","required":true,"placeholder":{"en":"e.g. People & Culture","fr":"p. ex. Personnes et culture"}}]'::jsonb, '[{"type":"title","text":{"en":"Code of Conduct","fr":"Code de conduite"}},{"type":"meta","text":{"en":"{{org}} · Effective {{effective_date}} · {{jurisdiction}}","fr":"{{org}} · En vigueur le {{effective_date}} · {{jurisdiction}}"}},{"type":"clause","text":{"en":"Everyone at {{org}} is entitled to a workplace free from discrimination, harassment, and violence.","fr":"Chacun chez {{org}} a droit à un milieu exempt de discrimination, de harcèlement et de violence."},"n":1,"heading":{"en":"Respectful conduct","fr":"Conduite respectueuse"}},{"type":"clause","text":{"en":"Concerns may be raised in good faith to {{contact}} without fear of reprisal.","fr":"Les préoccupations peuvent être soulevées de bonne foi auprès de {{contact}} sans crainte de représailles."},"n":2,"heading":{"en":"Raising concerns","fr":"Soulever une préoccupation"}},{"type":"ack","text":{"en":"I acknowledge I have read and understood this document.","fr":"Je reconnais avoir lu et compris le présent document."}},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"Human Rights Code — respectful workplace","fr":"Code des droits de la personne — milieu respectueux"},{"en":"Occupational Health and Safety Act","fr":"Loi sur la santé et la sécurité au travail"}]'::jsonb, '{"ON":{"en":"Align conduct expectations with OHSA workplace-harassment duties.","fr":"Aligner les attentes de conduite sur les obligations de la LSST."},"QC":{"en":"Reflect the psychological-harassment provisions of the LSA.","fr":"Refléter les dispositions sur le harcèlement psychologique de la LNT."},"FED":{"en":"Reflect the Work Place Harassment and Violence Prevention Regulations.","fr":"Refléter le Règlement sur la prévention du harcèlement et de la violence."}}'::jsonb, '[{"en":"Purpose & scope","fr":"Objet et portée"},{"en":"Respectful conduct","fr":"Conduite respectueuse"},{"en":"Conflicts of interest","fr":"Conflits d’intérêts"},{"en":"Company property","fr":"Biens de l’entreprise"},{"en":"Raising concerns","fr":"Soulever une préoccupation"},{"en":"Consequences","fr":"Conséquences"}]'::jsonb, '<h1 class="center">Code of Business Conduct and Ethics</h1>
<p class="center"><strong>Effective:</strong> <span class="mf">{{policy_effective_date}}</span></p>
<h2>Who this applies to</h2>
<p>This Code applies to everyone at <span class="mf">{{employer_legal_name}}</span> — employees, officers, directors, contractors and anyone else acting for us. If you are not sure what to do, ask.</p>
<h2>1. Our guiding principles</h2>
<p>Good business is built on a few simple things: telling the truth, keeping promises, treating people well, and taking responsibility when something goes wrong.</p>
<h2>2. Honesty and integrity</h2>
<p>Be truthful with customers, partners, colleagues, and regulators. If you make a mistake, say so — early and clearly.</p>
<h2>3. Respect and inclusion</h2>
<p>Discrimination, harassment and retaliation — on the basis of any ground protected by the Human Rights Code, R.S.O. 1990, c. H.19 — are not permitted. Our Harassment, Discrimination and Violence Prevention Policy sets out the details.</p>
<h2>4. Conflicts of interest</h2>
<p>Avoid situations where your personal interests could reasonably conflict with your duty to the Company. When in doubt, disclose to your manager or <span class="mf">{{ethics_contact_name}}</span>.</p>
<h2>5. Bribery, gifts and entertainment</h2>
<p>We do not give or accept bribes or anything that would compromise our judgment, consistent with Canada''s Corruption of Foreign Public Officials Act, S.C. 1998, c. 34.</p>
<h2>6. Fair dealing</h2>
<p>Compete on the merits of what we offer. When a contract is in place, we act in good faith and with honesty, consistent with <em>Bhasin v. Hrynew</em>, 2014 SCC 71.</p>
<h2>7. Protection of Company assets</h2>
<p>Use Company assets for legitimate business purposes and take reasonable care of them.</p>
<h2>8. Accurate books and records</h2>
<p>Our financial and business records must accurately reflect underlying transactions.</p>
<h2>9. Confidentiality and privacy</h2>
<p>Keep confidential information confidential. Handle personal information in accordance with PIPEDA (federal baseline).</p>
<h2>10. Insider information</h2>
<p>Do not trade on or share material non-public information about the Company.</p>
<h2>11. Health, safety and the environment</h2>
<p>Follow our health, safety and environmental policies. You have the right to refuse unsafe work under the Occupational Health and Safety Act, R.S.O. 1990, c. O.1.</p>
<h2>12. Social media and external communications</h2>
<p>You are personally responsible for what you post online. When in doubt, ask <span class="mf">{{ethics_contact_name}}</span> before posting.</p>
<h2>13. Reporting a concern</h2>
<p>If you see something that is — or might be — a violation of this Code, report it to your manager, HR, or (for anonymous reports) <span class="mf">{{whistleblower_channel}}</span>. We will not retaliate against anyone who reports in good faith.</p>
<h2>14. Consequences of violating this Code</h2>
<p>Violations can lead to disciplinary action, up to and including termination, consistent with <em>McKinley v. BC Tel</em>, 2001 SCC 38.</p>
<h2>15. Review and updates</h2>
<p>This Code is reviewed annually. The current version is available at <span class="mf">{{policy_url}}</span>.</p>', '2026-01-10', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t13', 'policies', 'harassment_policy', 'T13', 'policy', true, 'org', 'Harassment, discrimination & violence policy', 'Politique sur le harcèlement, la discrimination et la violence', 'A legally required policy in every Canadian jurisdiction. Defines prohibited conduct, reporting, and investigation.', 'Une politique exigée par la loi dans toutes les juridictions. Définit la conduite interdite, le signalement et l’enquête.', array['ON','QC','FED']::text[], 'medium', 'hr_review_required', false, 9, 88, '2026-02-01', '2026-06-16');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t13_v4', 'tpl_t13', 4, '[{"id":"effective_date","section":{"en":"Basics","fr":"Bases"},"label":{"en":"Effective date","fr":"Date d’entrée en vigueur"},"type":"date","required":true},{"id":"report_to","section":{"en":"Reporting","fr":"Signalement"},"label":{"en":"Report incidents to","fr":"Signaler les incidents à"},"type":"text","required":true,"placeholder":{"en":"e.g. HR lead","fr":"p. ex. responsable RH"}},{"id":"alt_contact","section":{"en":"Reporting","fr":"Signalement"},"label":{"en":"Alternate contact (if respondent is the manager)","fr":"Contact alternatif (si le mis en cause est le gestionnaire)"},"type":"text","required":true,"placeholder":{"en":"e.g. Owner / external ombud","fr":"p. ex. propriétaire / ombudsman"}}]'::jsonb, '[{"type":"title","text":{"en":"Harassment, Discrimination & Violence Policy","fr":"Politique sur le harcèlement, la discrimination et la violence"}},{"type":"meta","text":{"en":"{{org}} · Effective {{effective_date}} · {{jurisdiction}}","fr":"{{org}} · En vigueur le {{effective_date}} · {{jurisdiction}}"}},{"type":"clause","text":{"en":"{{org}} is committed to a workplace free from harassment, discrimination, and violence, as required for {{jurisdiction}}.","fr":"{{org}} s’engage à offrir un milieu exempt de harcèlement, de discrimination et de violence, conformément aux exigences pour {{jurisdiction}}."},"n":1,"heading":{"en":"Commitment","fr":"Engagement"}},{"type":"clause","text":{"en":"Report incidents to {{report_to}}. If the report concerns that person, contact {{alt_contact}} instead. Reports are handled confidentially and investigated promptly. Reprisal is prohibited.","fr":"Signalez à {{report_to}}. Si le signalement concerne cette personne, contactez plutôt {{alt_contact}}. Les signalements sont confidentiels et font l’objet d’une enquête rapide. Les représailles sont interdites."},"n":2,"heading":{"en":"How to report","fr":"Comment signaler"}},{"type":"ack","text":{"en":"I acknowledge I have read and understood this document.","fr":"Je reconnais avoir lu et compris le présent document."}},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"OHSA — Bill 168 duties","fr":"LSST — obligations (projet 168)"},{"en":"LSA — psychological harassment","fr":"LNT — harcèlement psychologique"},{"en":"Work Place Harassment and Violence Prevention Regulations (federal)","fr":"Règlement fédéral sur le harcèlement et la violence"}]'::jsonb, '{"ON":{"en":"A written program, worker training, and a defined complaint procedure are mandatory under OHSA.","fr":"Un programme écrit, la formation et une procédure de plainte sont obligatoires (LSST)."},"QC":{"en":"Employers must adopt and make available a psychological-harassment prevention policy under the LSA.","fr":"Les employeurs doivent adopter et rendre disponible une politique de prévention du harcèlement psychologique (LNT)."},"FED":{"en":"The federal Regulations require risk assessments, training, and a resolution process with set timelines.","fr":"Le Règlement fédéral exige des évaluations, de la formation et un processus de résolution avec délais."}}'::jsonb, '[{"en":"Definitions","fr":"Définitions"},{"en":"Prohibited conduct","fr":"Conduite interdite"},{"en":"How to report","fr":"Comment signaler"},{"en":"Confidentiality","fr":"Confidentialité"},{"en":"Investigation process","fr":"Processus d’enquête"},{"en":"No reprisal","fr":"Aucune représailles"},{"en":"Support resources","fr":"Ressources de soutien"}]'::jsonb, '<h1 class="center">Workplace Harassment, Discrimination and Violence Prevention Policy</h1>
<p class="center"><strong>Effective:</strong> <span class="mf">{{policy_effective_date}}</span></p>
<h2>Our commitment</h2>
<p>Every person at <span class="mf">{{employer_legal_name}}</span> has the right to a workplace that is safe, respectful, and free from harassment, discrimination and violence. This is required by the Occupational Health and Safety Act, R.S.O. 1990, c. O.1, ss. 32.0.1–32.0.8 and the Human Rights Code, R.S.O. 1990, c. H.19.</p>
<h2>1. Who this applies to</h2>
<p>This policy applies to everyone who works for or with the Company, in any location where Company business is conducted, including remote workspaces and Company-related digital spaces.</p>
<h2>2. What we don''t allow</h2>
<p>The Company does not tolerate harassment, sexual harassment, discrimination on any protected ground, workplace violence, or retaliation against anyone who reports in good faith.</p>
<h2>3. How to report</h2>
<p>Contact <span class="mf">{{hr_contact_name}}</span> at <span class="mf">{{hr_contact_email}}</span> or <span class="mf">{{hr_contact_phone}}</span>, or use the confidential reporting channel at <span class="mf">{{confidential_reporting_channel}}</span>, which accepts anonymous reports. If you are in immediate danger, contact emergency services (911) first.</p>
<h2>4. How we investigate</h2>
<p>Reports are acknowledged promptly (normally within <span class="mf">{{ack_period}}</span>), investigated fairly and impartially, and both parties are informed of the outcome, normally within <span class="mf">{{results_period}}</span> of the conclusion of the investigation.</p>
<h2>5. Corrective actions</h2>
<p>Where a complaint is substantiated, corrective action proportionate to the conduct will follow, consistent with <em>McKinley v. BC Tel</em>, 2001 SCC 38 where termination is considered.</p>
<h2>6. Domestic violence</h2>
<p>If you are experiencing domestic violence, we will take reasonable steps to keep you safe at work and help you access support, including statutory domestic-violence leave where applicable. Contact <span class="mf">{{hr_contact_name}}</span> confidentially.</p>
<h2>7. Training and prevention</h2>
<p>All employees and managers receive training on this policy at onboarding and annually thereafter. Workplace violence risks are assessed at least annually.</p>
<h2>8. Third-party and client harassment</h2>
<p>Harassment can come from clients, customers, contractors, or other third parties. Report it to your manager or <span class="mf">{{hr_contact_name}}</span>; you will not be penalized for refusing to tolerate abusive conduct.</p>
<h2>9. Your statutory rights</h2>
<p>Nothing in this policy limits your right to file a complaint with the human rights commission, the labour standards regulator, or the OHS regulator. For employees in Québec, a psychological harassment complaint may be filed with the CNESST within 2 years of the last incident.</p>
<h2>10. Program review</h2>
<p>This policy is reviewed at least annually and updated to reflect changes in the law. The current version is posted at <span class="mf">{{policy_url}}</span>.</p>', '2026-02-01', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t14', 'termination', 'resignation_acceptance', 'T14', 'letter', true, 'employee', 'Resignation acceptance', 'Acceptation de démission', 'Confirms an employee’s resignation, the last day, and final-pay logistics — closing the record cleanly.', 'Confirme la démission d’un employé, le dernier jour et la paie finale — pour clore le dossier proprement.', array['ON','QC','FED']::text[], 'low', 'hr_review_required', false, 5, 33, '2026-02-01', '2026-05-05');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t14_v2', 'tpl_t14', 2, '[{"id":"employee_name","section":{"en":"Employee","fr":"Employé"},"label":{"en":"Employee full name","fr":"Nom complet de l’employé(e)"},"type":"text","required":true,"placeholder":{"en":"Full name","fr":"Nom complet"}},{"id":"last_day","section":{"en":"Timing","fr":"Échéancier"},"label":{"en":"Last day of work","fr":"Dernier jour de travail"},"type":"date","required":true}]'::jsonb, '[{"type":"title","text":{"en":"Acceptance of Resignation","fr":"Acceptation de démission"}},{"type":"meta","text":{"en":"{{org}} · {{today}}","fr":"{{org}} · {{today}}"}},{"type":"para","text":{"en":"Dear {{employee_name}}, we acknowledge and accept your resignation. Your last day of work will be {{last_day}}.","fr":"Cher/Chère {{employee_name}}, nous accusons réception et acceptons votre démission. Votre dernier jour sera le {{last_day}}."}},{"type":"clause","text":{"en":"Your final pay will include all earned wages and accrued vacation, issued within the timeframe required for {{jurisdiction}}. We will provide your Record of Employment.","fr":"Votre paie finale comprendra tous les salaires gagnés et les vacances accumulées, dans le délai exigé pour {{jurisdiction}}. Nous fournirons votre relevé d’emploi."},"n":1,"heading":{"en":"Final pay","fr":"Paie finale"}},{"type":"para","text":{"en":"Thank you for your contributions. We would be glad to provide a reference.","fr":"Merci de vos contributions. Nous serions heureux de fournir une référence."}},{"type":"sig","roles":[{"en":"Employer representative","fr":"Représentant de l’employeur"},{"en":"Employee","fr":"Employé(e)"}]},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"ESA, 2000 — final pay & vacation payout","fr":"LNE, 2000 — paie finale et vacances"},{"en":"Record of Employment obligations","fr":"Obligations du relevé d’emploi"}]'::jsonb, '{"ON":{"en":"Pay all earned wages and accrued vacation by the ESA deadline; issue the ROE.","fr":"Verser tous les salaires gagnés et les vacances accumulées dans le délai LNE; émettre le relevé d’emploi."},"QC":{"en":"Provide the final pay and the relevé d’emploi promptly per LSA and federal EI rules.","fr":"Fournir la paie finale et le relevé d’emploi rapidement selon la LNT et l’assurance-emploi."},"FED":{"en":"Follow Canada Labour Code final-pay timing and issue the ROE.","fr":"Suivre les délais de paie finale du CCT et émettre le relevé d’emploi."}}'::jsonb, '[{"en":"Acknowledgement","fr":"Accusé de réception"},{"en":"Last day of work","fr":"Dernier jour"},{"en":"Final pay & vacation","fr":"Paie finale et vacances"},{"en":"Return of property","fr":"Retour des biens"},{"en":"Thanks & reference","fr":"Remerciements et référence"}]'::jsonb, '<h1 class="center">Acceptance of Resignation</h1>
<p class="date"><span class="mf">{{document_date}}</span></p>
<address><span class="mf">{{employee_name}}</span><br><span class="mf">{{employee_address_line_1}}</span><br><span class="mf">{{employee_address_line_2}}</span></address>
<p class="re"><strong>Re:</strong> Acknowledgement of your resignation</p>
<p>Dear <span class="mf">{{employee_first_name}}</span>,</p>
<p>Thank you for letting us know about your decision to resign from your position as <strong><span class="mf">{{position_title}}</span></strong> at <strong><span class="mf">{{employer_legal_name}}</span></strong>. We received your notice on <span class="mf">{{resignation_notice_date}}</span>, and this letter confirms what we have agreed.</p>
<h2>1. Your last day of work</h2>
<p>Your last day of active employment will be <span class="mf">{{last_day_of_work}}</span>. We have accepted this date as your effective resignation date.</p>
<h2>2. Final pay and vacation</h2>
<p>Your final pay, including any wages owing up to and including <span class="mf">{{last_day_of_work}}</span>, plus vacation pay accrued but not yet taken, will be deposited no later than your next regular pay date (ESA s. 11).</p>
<h2>3. Benefits and group insurance</h2>
<p>Your participation in the Company''s group benefits plan will continue until <span class="mf">{{benefits_end_date}}</span>. After that date, you may be eligible to convert certain coverages to an individual policy without a medical exam.</p>
<h2>4. Return of Company property</h2>
<p>Please return any Company property in your possession on or before your last day — including your laptop, access card, phone, keys, and any physical or electronic files containing Company information.</p>
<h2>5. Record of Employment</h2>
<p>Your Record of Employment (ROE) will be issued electronically to Service Canada within 5 calendar days of your last day of work, in accordance with the Employment Insurance Regulations, SOR/96-332.</p>
<h2>6. Ongoing obligations</h2>
<p>Confidentiality and any intellectual property assignment obligations under your employment agreement continue to apply after your last day.</p>
<h2>7. Knowledge transfer</h2>
<p>Between now and your last day, we''d appreciate your help with a handover of your active projects. Your manager, <span class="mf">{{manager_name}}</span>, will work with you on a simple plan.</p>
<h2>8. References and future contact</h2>
<p>We''re happy to provide a professional reference. Please direct reference requests to <span class="mf">{{reference_contact_name}}</span> at <span class="mf">{{reference_contact_email}}</span>.</p>
<h2>9. Thank you</h2>
<p>Thank you for everything you''ve contributed during your time with us. We wish you the very best in what comes next.</p>
<p class="signoff-closing">With appreciation,</p>
<p class="signoff-name"><span class="mf">{{employer_signer_name}}</span></p>
<p class="signoff-line"><span class="mf">{{employer_signer_title}}</span></p>
<p class="signoff-line"><span class="mf">{{employer_legal_name}}</span></p>', '2026-02-01', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t15', 'termination', 'group_termination_notice', 'T15', 'notice', true, 'org', 'Group termination notice', 'Avis de licenciement collectif', 'For terminating 50+ employees in a short window. Triggers enhanced notice and government-notification duties.', 'Pour la cessation de 50 employés et plus dans une courte période. Déclenche un avis bonifié et l’obligation d’aviser le gouvernement.', array['ON','QC','FED']::text[], 'high', 'lawyer_review_recommended', true, 11, 6, '2026-01-30', '2026-06-16');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t15_v2', 'tpl_t15', 2, '[{"id":"employee_count","section":{"en":"Scope","fr":"Portée"},"label":{"en":"Number of employees affected","fr":"Nombre d’employés touchés"},"type":"number","required":true,"placeholder":{"en":"e.g. 60","fr":"p. ex. 60"}},{"id":"effective_date","section":{"en":"Timing","fr":"Échéancier"},"label":{"en":"Termination effective date","fr":"Date d’effet"},"type":"date","required":true},{"id":"notice_weeks","section":{"en":"Entitlements","fr":"Droits"},"label":{"en":"Enhanced notice (weeks)","fr":"Avis bonifié (semaines)"},"type":"number","required":true,"hint":{"en":"Scales with the number of employees under the applicable statute.","fr":"Proportionnel au nombre d’employés selon la loi applicable."}}]'::jsonb, '[{"type":"title","text":{"en":"Group Termination Notice","fr":"Avis de licenciement collectif"}},{"type":"meta","text":{"en":"{{org}} · {{today}} · {{jurisdiction}}","fr":"{{org}} · {{today}} · {{jurisdiction}}"}},{"type":"clause","text":{"en":"This notice affects {{employee_count}} employees, with terminations effective {{effective_date}}.","fr":"Le présent avis touche {{employee_count}} employés, avec effet le {{effective_date}}."},"n":1,"heading":{"en":"Affected group","fr":"Groupe touché"}},{"type":"clause","text":{"en":"Affected employees receive {{notice_weeks}} weeks of enhanced notice, and the applicable Minister for {{jurisdiction}} will be notified as required.","fr":"Les employés touchés reçoivent {{notice_weeks}} semaines d’avis bonifié, et le ministre applicable pour {{jurisdiction}} sera avisé comme l’exige la loi."},"n":2,"heading":{"en":"Enhanced notice & notification","fr":"Avis bonifié et notification"}},{"type":"clause","text":{"en":"Re-employment and outplacement support will be offered to all affected employees.","fr":"Un soutien à la réembauche et au reclassement sera offert à tous les employés touchés."},"n":3,"heading":{"en":"Support","fr":"Soutien"}},{"type":"clause","text":{"en":"This workplace is unionized: the collective agreement and its grievance procedure govern this process, and this document must follow the negotiated steps and timelines.","fr":"Ce milieu de travail est syndiqué : la convention collective et sa procédure de grief régissent ce processus, et le présent document doit suivre les étapes et les délais négociés."},"heading":{"en":"Collective agreement","fr":"Convention collective"},"when":{"union":true}},{"type":"sig","roles":[{"en":"Employer representative","fr":"Représentant de l’employeur"},{"en":"Employee","fr":"Employé(e)"}]},{"type":"note","text":{"en":"Higher-risk document. Lawyer review is recommended before this is sent or signed. Dutiva does not provide legal advice.","fr":"Document à risque élevé. Une révision juridique est recommandée avant l’envoi ou la signature. Dutiva ne fournit pas de conseils juridiques."},"tone":"risk"}]'::jsonb, '[{"en":"ESA, 2000 ss. 58–59 — mass termination","fr":"LNE, 2000 art. 58–59 — licenciement collectif"},{"en":"Canada Labour Code ss. 212–214 — group termination","fr":"Code canadien du travail art. 212–214 — licenciement collectif"},{"en":"Ministry / ministère notification","fr":"Avis au ministère"}]'::jsonb, '{"ON":{"en":"Terminating 50+ employees in 4 weeks triggers enhanced ESA notice (8–16 weeks) and Ministry Form 1.","fr":"La cessation de 50 employés et plus en 4 semaines déclenche un avis LNE bonifié (8–16 semaines) et le formulaire 1 du ministère."},"QC":{"en":"The LSA requires notice to the Minister scaled by the number of employees affected.","fr":"La LNT exige un avis au ministre proportionnel au nombre d’employés touchés."},"FED":{"en":"CLC group-termination provisions require notice to the Minister and a joint planning committee.","fr":"Les dispositions du CCT exigent un avis au ministre et un comité mixte de planification."}}'::jsonb, '[{"en":"Affected group & count","fr":"Groupe touché et nombre"},{"en":"Enhanced notice period","fr":"Période d’avis bonifiée"},{"en":"Government notification","fr":"Avis au gouvernement"},{"en":"Support & re-employment","fr":"Soutien et réembauche"},{"en":"Individual entitlements","fr":"Droits individuels"}]'::jsonb, '<h1 class="center">Notice of Group Termination of Employment</h1>
<p class="center"><strong>Issued by:</strong> <span class="mf">{{employer_legal_name}}</span> &nbsp;•&nbsp; <strong>Date:</strong> <span class="mf">{{notice_date}}</span></p>
<p>This notice is provided to employees affected by a group termination of employment, to the Minister of Labour (or equivalent authority), and — where required — to the employees'' bargaining agent. We are issuing it because 50 or more employees are affected within a 4-week period.</p>
<h2>1. Why this is happening</h2>
<p><span class="mf">{{employer_legal_name}}</span> has made the difficult decision to eliminate approximately <span class="mf">{{affected_headcount}}</span> positions at <span class="mf">{{affected_location}}</span>, effective <span class="mf">{{effective_date}}</span>, for the following reason: <span class="mf">{{reason_for_group_termination}}</span>.</p>
<h2>2. Legal framework</h2>
<p>Group terminations in Canada are subject to enhanced notice rules. In Ontario: ESA s. 58; O. Reg. 288/01 (Form 1 required for 50+ employees). This group notice does not reduce any individual''s entitlements under their contract, the common law, or any collective agreement.</p>
<h2>3. Notice period and last day of work</h2>
<p>Affected employees will receive working notice beginning on <span class="mf">{{notice_date}}</span>, with a last day of work on <span class="mf">{{effective_date}}</span>. The statutory notice period applicable to this group termination is <span class="mf">{{statutory_notice_weeks}}</span> weeks, based on the headcount of affected employees.</p>
<h2>4. Severance, termination pay and individual entitlements</h2>
<p>In addition to statutory notice, affected employees may be entitled to statutory severance pay where applicable legislation provides for it. The details are set out in each individual''s termination letter.</p>
<h2>5. Continuation of benefits</h2>
<p>Group benefits coverage will continue through the statutory notice period at minimum. Specific end dates are set out in each affected employee''s individual notice.</p>
<h2>6. Employment Insurance and Record of Employment</h2>
<p>Records of Employment will be issued promptly in accordance with the Employment Insurance Regulations, SOR/96-332, s. 19(3).</p>
<h2>7. Career transition support</h2>
<p>The Company is providing the following career transition support to affected employees: <span class="mf">{{career_transition_support}}</span>.</p>
<h2>8. Union and bargaining agent notification</h2>
<p>Where affected employees are represented by a union, that organization has been or is being notified at the same time as this notice.</p>
<h2>9. Employee and Family Assistance Program</h2>
<p>Our Employee and Family Assistance Program (EFAP) is available to all affected employees and their immediate family members at no cost through the transition period. Contact the EFAP at <span class="mf">{{efap_contact}}</span>.</p>
<h2>10. Questions and contact</h2>
<p>Please reach out to <span class="mf">{{hr_contact_name}}</span> at <span class="mf">{{hr_contact_email}}</span> or <span class="mf">{{hr_contact_phone}}</span>. We will also hold information sessions on <span class="mf">{{info_session_dates}}</span> for any affected employee who would like to attend.</p>', '2026-01-30', 'handoff-seed');
insert into doclib.document_templates (id, category_id, template_key, tid, kind, core, subject, name_en, name_fr, desc_en, desc_fr, jurisdictions_supported, risk_level, review_status, requires_lawyer_review, est_minutes, usage_count, effective_date, updated_at) values ('tpl_t16', 'discipline', 'performance_improvement_plan', 'T16', 'plan', true, 'employee', 'Performance improvement plan (PIP)', 'Plan d’amélioration du rendement (PAR)', 'A structured, time-boxed plan with clear goals, support, and check-ins. Framed as help first, not a paper trail.', 'Un plan structuré et limité dans le temps, avec objectifs clairs, soutien et suivis. Conçu comme un appui, non un dossier.', array['ON','QC','FED']::text[], 'medium', 'hr_review_required', false, 9, 44, '2026-03-01', '2026-06-16');
insert into doclib.document_template_versions (id, template_id, version_number, question_flow_json, clause_library_json, statutory_references_json, jurisdiction_notes_json, includes_json, body_content, effective_date, created_by) values ('tpl_t16_v3', 'tpl_t16', 3, '[{"id":"employee_name","section":{"en":"Employee","fr":"Employé"},"label":{"en":"Employee full name","fr":"Nom complet de l’employé(e)"},"type":"text","required":true,"placeholder":{"en":"Full name","fr":"Nom complet"}},{"id":"goals","section":{"en":"Goals","fr":"Objectifs"},"label":{"en":"Improvement goals","fr":"Objectifs d’amélioration"},"type":"textarea","required":true,"placeholder":{"en":"Specific, measurable goals and the standard expected.","fr":"Objectifs précis et mesurables, et la norme attendue."}},{"id":"support","section":{"en":"Support","fr":"Soutien"},"label":{"en":"Support provided","fr":"Soutien fourni"},"type":"textarea","required":true,"placeholder":{"en":"Coaching, training, tools, or adjusted workload.","fr":"Coaching, formation, outils ou charge ajustée."}},{"id":"review_period","section":{"en":"Timing","fr":"Échéancier"},"label":{"en":"Review period","fr":"Période de révision"},"type":"select","required":true,"options":[{"value":"30 days","label":{"en":"30 days","fr":"30 jours"}},{"value":"60 days","label":{"en":"60 days","fr":"60 jours"}},{"value":"90 days","label":{"en":"90 days","fr":"90 jours"}}]}]'::jsonb, '[{"type":"title","text":{"en":"Performance Improvement Plan","fr":"Plan d’amélioration du rendement"}},{"type":"meta","text":{"en":"{{org}} · {{today}} · Confidential","fr":"{{org}} · {{today}} · Confidentiel"}},{"type":"para","text":{"en":"This plan is designed to help {{employee_name}} succeed. It sets clear goals and the support {{org}} will provide over the next {{review_period}}.","fr":"Ce plan vise à aider {{employee_name}} à réussir. Il fixe des objectifs clairs et le soutien que {{org}} offrira au cours des prochains {{review_period}}."}},{"type":"clause","text":{"en":"{{goals}}","fr":"{{goals}}"},"n":1,"heading":{"en":"Goals","fr":"Objectifs"}},{"type":"clause","text":{"en":"{{support}} We will check in regularly and review together at the end of the {{review_period}} period.","fr":"{{support}} Nous ferons des suivis réguliers et réviserons ensemble à la fin de la période de {{review_period}}."},"n":2,"heading":{"en":"Support we’ll provide","fr":"Soutien fourni"}},{"type":"clause","text":{"en":"This workplace is unionized: the collective agreement and its grievance procedure govern this process, and this document must follow the negotiated steps and timelines.","fr":"Ce milieu de travail est syndiqué : la convention collective et sa procédure de grief régissent ce processus, et le présent document doit suivre les étapes et les délais négociés."},"heading":{"en":"Collective agreement","fr":"Convention collective"},"when":{"union":true}},{"type":"sig","roles":[{"en":"Employer representative","fr":"Représentant de l’employeur"},{"en":"Employee","fr":"Employé(e)"}]},{"type":"note","text":{"en":"Generated from your answers as a starting point. Review before use — Dutiva provides compliance-oriented HR guidance, not legal advice.","fr":"Généré à partir de vos réponses comme point de départ. À réviser avant usage — Dutiva offre un accompagnement RH axé sur la conformité, non des conseils juridiques."},"tone":"info"}]'::jsonb, '[{"en":"Progressive-discipline & good-faith principles","fr":"Principes de discipline progressive et de bonne foi"},{"en":"Human Rights Code — accommodation duty","fr":"Code des droits de la personne — obligation d’adaptation"}]'::jsonb, '{"ON":{"en":"Screen for an accommodation need before and during the plan; keep goals objective and documented.","fr":"Vérifier un besoin d’adaptation avant et pendant le plan; garder des objectifs objectifs et documentés."},"QC":{"en":"Good faith and fair process are required; the plan should be realistic and supported.","fr":"La bonne foi et l’équité procédurale sont requises; le plan doit être réaliste et soutenu."},"FED":{"en":"A documented, supportive plan strengthens the record if unjust-dismissal review follows.","fr":"Un plan documenté et soutenu renforce le dossier en cas d’examen pour congédiement injuste."}}'::jsonb, '[{"en":"Goals & measures","fr":"Objectifs et mesures"},{"en":"Support & resources","fr":"Soutien et ressources"},{"en":"Check-in schedule","fr":"Calendrier de suivi"},{"en":"Review period","fr":"Période de révision"},{"en":"Possible outcomes","fr":"Résultats possibles"}]'::jsonb, '<h1 class="center">Performance Improvement Plan</h1>
<p class="center"><strong>Employee:</strong> <span class="mf">{{employee_name}}</span> &nbsp;•&nbsp; <strong>Role:</strong> <span class="mf">{{position_title}}</span> &nbsp;•&nbsp; <strong>Manager:</strong> <span class="mf">{{manager_name}}</span></p>
<p class="center"><strong>PIP Start:</strong> <span class="mf">{{pip_start_date}}</span> &nbsp;•&nbsp; <strong>PIP End:</strong> <span class="mf">{{pip_end_date}}</span> &nbsp;•&nbsp; <strong>Review Cadence:</strong> <span class="mf">{{pip_review_cadence}}</span></p>
<p>This Performance Improvement Plan (PIP) exists because we believe you can succeed in your role at <span class="mf">{{employer_legal_name}}</span>, and we want to give you clear, fair support to get there. A PIP is not a disciplinary measure and is not, by itself, a step toward termination.</p>
<h2>1. Why we are having this conversation</h2>
<p>Over the past period, the following areas of your performance have not met the expectations of your role: <span class="mf">{{performance_concerns_summary}}</span>.</p>
<h2>2. Expectations for the PIP period</h2>
<ul><li><strong>Expectation 1:</strong> <span class="mf">{{expectation_1}}</span></li><li><strong>Expectation 2:</strong> <span class="mf">{{expectation_2}}</span></li><li><strong>Expectation 3:</strong> <span class="mf">{{expectation_3}}</span></li></ul>
<h2>3. Support the Company will provide</h2>
<p>Coaching and feedback on <span class="mf">{{coaching_cadence}}</span>; training and resources: <span class="mf">{{training_resources}}</span>; accommodation where a concern relates to a protected ground under the Human Rights Code, R.S.O. 1990, c. H.19 and the <em>Meiorin</em> standard.</p>
<h2>4. Check-ins and progress reviews</h2>
<p>Your manager will meet with you <span class="mf">{{pip_review_cadence}}</span> throughout the PIP period to discuss progress and adjust the plan where it makes sense.</p>
<h2>5. What happens at the end of the PIP</h2>
<p>One of the following will happen: <strong>Successful completion</strong> — the PIP closes and you continue in your role; <strong>Extension</strong> — where fair and realistic; or <strong>Further action</strong> — up to and including termination, assessed contextually under <em>McKinley v. BC Tel</em>, 2001 SCC 38, and with your ESA ss. 54–57 entitlements fully respected.</p>
<h2>6. Your rights during this process</h2>
<p>You have the right to clear feedback, to ask questions, to raise concerns without fear of retaliation, and to reasonable accommodation where human rights legislation requires it.</p>
<h2>7. Documentation</h2>
<p>A complete written record of this PIP process will be maintained, including this document and notes from each check-in, retained for a minimum of 3 years after employment ends.</p>
<h2>8. Acknowledgement</h2>
<p>Your signature below confirms that you have received a copy of this PIP and that it has been discussed with you. It does not mean you agree with every point — you may submit a written response.</p>
<div class="spacer">&nbsp;</div>
<table class="sig"><tr>
<td><div class="sig-line">_______________________________</div><div class="sig-under">Signature — <span class="mf">{{employer_signer_name}}</span></div><div class="sig-under"><span class="mf">{{employer_signer_title}}</span></div><div class="sig-under">Date: <span class="mf">{{employer_signature_date}}</span></div><div class="sig-label">MANAGER</div></td>
<td><div class="sig-line">_______________________________</div><div class="sig-under">Signature — <span class="mf">{{employee_name}}</span></div><div class="sig-under"><span class="mf">{{employee_position}}</span></div><div class="sig-under">Date: <span class="mf">{{employee_signature_date}}</span></div><div class="sig-label">EMPLOYEE — RECEIVED AND DISCUSSED</div></td>
</tr></table>', '2026-03-01', 'handoff-seed');
